window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2022-1"]={"track":"written","round":"2022-1","questions":[{"id":"written-2022-1-1","no":1,"unit":"소프트웨어 설계","q":"User Interface 설계 시 오류 메시지나 경고에 관한 지침으로 가장 거리가 먼 것은?","choices":["메시지는 이해하기 쉬워야 한다.","오류로부터 회복을 위한 구체적인 설명이 제공되어야 한다.","오류로 인해 발생 될 수 있는 부정적인 내용을 적극적으로 사용자들에게 알려야 한다.","소리나 색의 사용을 줄이고 텍스트로만 전달하도록 한다."],"ans":4,"rate":85,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"}],"exp":{"concept":"오류 메시지는 사용자가 무엇이 잘못됐고 어떻게 고치면 되는지 바로 알 수 있게 만들어야 한다. 그래서 쉬운 말로 쓰고, 회복 방법을 구체적으로 알려 주고, 눈에 잘 띄도록 소리나 색도 함께 활용한다. 자동차 계기판의 경고등이 빨간색으로 켜지고 경고음이 울리는 것과 같은 원리다.","choices":[{"verdict":"오답","why":"오류 메시지는 전문 용어 대신 사용자가 이해하기 쉬운 말로 써야 한다. 올바른 지침이다."},{"verdict":"오답","why":"무엇을 하면 오류에서 벗어날 수 있는지 구체적으로 안내해야 한다. 올바른 지침이다."},{"verdict":"오답","why":"오류 때문에 생길 수 있는 부정적인 결과(데이터 손실 등)를 사용자에게 적극적으로 알려야 한다. 올바른 지침이다."},{"verdict":"정답","why":"오류나 경고는 눈에 잘 띄어야 하므로 소리나 색을 함께 사용하는 것이 권장된다. 텍스트로만 전달하라는 것은 지침과 반대다."}],"keywords":[{"term":"UI 오류 메시지 지침","desc":"이해하기 쉽게, 회복 방법을 구체적으로, 부정적 결과는 적극적으로 알리고, 소리·색으로 눈에 띄게"},{"term":"UI 설계 원칙","desc":"직관성, 유효성, 학습성, 유연성"}],"memo":"경고는 '눈에 띄어야' 한다. 소리·색을 줄이라는 보기는 거꾸로 된 지침이다."}},{"id":"written-2022-1-2","no":2,"unit":"소프트웨어 설계","q":"다음 중 애자일(Agile) 소프트웨어 개발에 대한 설명으로 틀린 것은?","choices":["공정과 도구보다 개인과의 상호작용을 더 가치 있게 여긴다.","동작하는 소프트웨어보다는 포괄적인 문서를 가치 있게 여긴다.","계약 협상보다는 고객과의 협력을 가치 있게 여긴다.","계획을 따르기보다 변화에 대응하기를 가치 있게 여긴다."],"ans":2,"rate":89,"wiki":[{"title":"애자일","url":"https://itwiki.kr/w/애자일"},{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"애자일(Agile)은 변화에 빠르게 대응하며 짧은 주기로 동작하는 소프트웨어를 만들어 가는 개발 방식이다. 애자일 선언문의 네 가지 가치는 모두 공정·도구, 문서, 계약, 계획 같은 형식보다 사람, 동작하는 소프트웨어, 고객과의 협력, 변화 대응을 더 중시한다는 내용이다.","choices":[{"verdict":"오답","why":"애자일 선언문의 첫째 가치: 공정과 도구보다 개인과 상호작용을 더 중시한다. 맞는 설명이다."},{"verdict":"정답","why":"애자일 선언문은 '포괄적인 문서보다 동작하는 소프트웨어'를 더 가치 있게 여긴다. 보기는 순서를 거꾸로 뒤집었으므로 틀린 설명이다."},{"verdict":"오답","why":"애자일 선언문의 셋째 가치: 계약 협상보다 고객과의 협력을 더 중시한다. 맞는 설명이다."},{"verdict":"오답","why":"애자일 선언문의 넷째 가치: 계획을 따르기보다 변화에 대응하는 것을 더 중시한다. 맞는 설명이다."}],"keywords":[{"term":"애자일 선언문 4가치","desc":"개인과 상호작용, 동작하는 소프트웨어, 고객과의 협력, 변화에 대응"},{"term":"애자일 대표 기법","desc":"XP(eXtreme Programming), 스크럼(Scrum), 칸반(Kanban), 린(Lean), FDD(Feature Driven Development)"}],"memo":"애자일은 문서·계약·계획·도구보다 '사람·작동하는 결과·협력·변화'를 앞세운다. 문서를 더 중시한다는 보기는 함정이다."}},{"id":"written-2022-1-3","no":3,"unit":"소프트웨어 설계","q":"소프트웨어 설계에서 요구사항 분석에 대한 설명으로 틀린 것은?","choices":["소프트웨어가 무엇을 해야하는가를 추적하여 요구사항 명세를 작성하는 작업이다.","사용자의 요구를 추출하여 목표를 정하고 어떤 방식으로 해결할 것인지 결정하는 단계이다.","소프트웨어 시스템이 사용되는 동안 발견되는 오류를 정리하는 단계이다.","소프트웨어 개발의 출발점이면서 실질적인 첫 번째 단계이다."],"ans":3,"rate":86,"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"}],"exp":{"concept":"요구사항 분석은 소프트웨어 개발의 첫 단계로, 사용자가 원하는 것을 끌어내어 '무엇을 만들지'를 정하고 명세서로 정리하는 작업이다. 이미 만들어진 소프트웨어를 쓰다가 발견한 오류를 정리하는 일은 개발이 끝난 뒤의 유지보수 단계에서 한다.","choices":[{"verdict":"오답","why":"요구사항 분석은 소프트웨어가 무엇을 해야 하는지 파악해 요구사항 명세를 작성하는 작업이다. 맞는 설명이다."},{"verdict":"오답","why":"사용자의 요구를 추출해 목표를 정하고 해결 방식을 결정하는 단계이다. 맞는 설명이다."},{"verdict":"정답","why":"시스템이 사용되는 동안 발견되는 오류를 정리하고 고치는 것은 유지보수(Maintenance) 단계의 일이다. 요구사항 분석에 대한 설명이 아니다."},{"verdict":"오답","why":"요구사항 분석은 소프트웨어 개발의 출발점이자 실질적인 첫 번째 단계이다. 맞는 설명이다."}],"keywords":[{"term":"요구사항 분석","desc":"사용자 요구를 추출·분석해 무엇을 만들지 정하고 명세서로 작성하는 개발의 첫 단계"},{"term":"요구사항 개발 프로세스","desc":"도출(Elicitation) → 분석(Analysis) → 명세(Specification) → 확인(Validation)"},{"term":"유지보수","desc":"운영 중 발견된 오류 수정, 환경 변화 대응, 기능 개선을 하는 단계"}],"memo":"'사용되는 동안'이라는 말이 나오면 개발 시작 단계가 아니라 유지보수 단계다."}},{"id":"written-2022-1-4","no":4,"unit":"소프트웨어 설계","q":"객체지향 기법에서 상위 클래스의 메소드와 속성을 하위 클래스가 물려받는 것을 의미하는 것은?","choices":["Abstraction","Polymorphism","Encapsulation","Inheritance"],"ans":4,"rate":76,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"객체지향에서 상속은 부모(상위) 클래스가 가진 속성과 메소드를 자식(하위) 클래스가 그대로 물려받는 것이다. 자식은 물려받은 것에 자기만의 기능을 더할 수 있어서 같은 코드를 반복해 쓰지 않아도 된다. 부모의 재산을 자식이 물려받는 것과 같다.","choices":[{"verdict":"오답","why":"Abstraction(추상화)은 불필요한 세부 사항은 숨기고 핵심 특징만 뽑아 표현하는 것이다. 물려받는 것과는 다르다."},{"verdict":"오답","why":"Polymorphism(다형성)은 같은 이름의 메소드가 객체에 따라 다르게 동작하는 성질이다(오버로딩, 오버라이딩)."},{"verdict":"오답","why":"Encapsulation(캡슐화)은 데이터와 그 데이터를 다루는 함수를 하나로 묶고 내부를 외부로부터 숨기는 것이다."},{"verdict":"정답","why":"Inheritance(상속)는 상위 클래스의 속성과 메소드를 하위 클래스가 물려받는 것이다."}],"keywords":[{"term":"상속(Inheritance)","desc":"상위 클래스의 속성·메소드를 하위 클래스가 물려받음"},{"term":"캡슐화(Encapsulation)","desc":"데이터와 함수를 묶고 내부 정보를 숨김(정보 은닉)"},{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체마다 다르게 반응함"},{"term":"추상화(Abstraction)","desc":"핵심 특징만 뽑아 단순하게 표현함"}],"memo":"Inheritance는 '유산(inheritance)'이라는 뜻 그대로 '물려받기'다."}},{"id":"written-2022-1-5","no":5,"unit":"소프트웨어 설계","q":"설계 기법 중 하향식 설계 방법과 상향식 설계 방법에 대한 비교 설명으로 가장 옳지 않은 것은?","choices":["하향식 설계에서는 통합 검사 시 인터페이스가 이미 정의되어 있어 통합이 간단하다.","하향식 설계에서 레벨이 낮은 데이터 구조의 세부 사항은 설계초기 단계에서 필요하다.","상향식 설계는 최하위 수준에서 각각의 모듈들을 설계하고 이러한 모듈이 완성되면 이들을 결합하여 검사한다.","상향식 설계에서는 인터페이스가 이미 성립되어 있지 않더라도 기능 추가가 쉽다."],"ans":4,"rate":58,"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"}],"exp":{"concept":"하향식 설계는 큰 틀(최상위 모듈)부터 정하고 점점 세부 모듈로 내려가는 방식이고, 상향식 설계는 가장 아래의 작은 모듈부터 만들어 위로 조립해 가는 방식이다. 상향식은 부품을 먼저 만들기 때문에, 부품끼리 맞물리는 인터페이스가 먼저 정해져 있어야 나중에 기능을 붙이기 쉽다.","choices":[{"verdict":"오답","why":"하향식 설계는 위에서부터 인터페이스를 먼저 정의하므로, 통합 검사 때 인터페이스가 이미 정해져 있어 통합이 간단하다. 맞는 설명이다."},{"verdict":"오답","why":"하향식 설계에서는 낮은 레벨의 데이터 구조 세부 사항도 설계 초기 단계에서 필요하다. 교재에서 하향식 설계의 특징으로 드는 내용이다."},{"verdict":"오답","why":"상향식 설계는 최하위 모듈부터 설계하고, 완성된 모듈들을 결합하며 검사한다. 맞는 설명이다."},{"verdict":"정답","why":"상향식 설계에서는 인터페이스가 이미 성립되어 있어야 기능 추가가 쉽다. 인터페이스가 없어도 쉽다는 설명은 틀렸다."}],"keywords":[{"term":"하향식 설계(Top-Down)","desc":"최상위 모듈부터 설계해 아래로 세분화, 통합 시 인터페이스가 이미 정의됨"},{"term":"상향식 설계(Bottom-Up)","desc":"최하위 모듈부터 설계해 위로 결합, 인터페이스가 먼저 성립되어야 기능 추가가 쉬움"}],"memo":"상향식은 부품부터 만든다. 부품끼리 맞물릴 규격(인터페이스)이 없으면 조립이 어렵다고 기억하자."}},{"id":"written-2022-1-6","no":6,"unit":"소프트웨어 설계","q":"자료흐름도(DFD)의 각 요소별 표기 형태의 연결이 옳지 않은 것은?","choices":["Process : 원","Data Flow : 화살표","Data Store : 삼각형","Terminator : 사각형"],"ans":3,"rate":80,"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"}],"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 데이터가 시스템 안에서 어떻게 흘러가고 처리되는지를 네 가지 기호로 그린 그림이다. 처리 과정은 원, 데이터의 흐름은 화살표, 데이터 저장소는 평행선(두 줄), 외부 개체(단말)는 사각형으로 그린다.","choices":[{"verdict":"오답","why":"프로세스(Process)는 원(버블)으로 표기한다. 올바른 연결이다."},{"verdict":"오답","why":"자료 흐름(Data Flow)은 화살표로 표기한다. 올바른 연결이다."},{"verdict":"정답","why":"자료 저장소(Data Store)는 평행선(위아래 두 줄)으로 표기한다. 삼각형이 아니므로 틀린 연결이다."},{"verdict":"오답","why":"단말(Terminator, 외부 개체)은 사각형으로 표기한다. 올바른 연결이다."}],"keywords":[{"term":"DFD 4요소","desc":"프로세스(원), 자료 흐름(화살표), 자료 저장소(평행선), 단말(사각형)"},{"term":"버블 차트","desc":"프로세스를 원(버블)으로 그리기 때문에 DFD를 버블 차트라고도 부름"}],"memo":"DFD에 삼각형은 없다. 원·화살표·두 줄·네모 네 가지만 기억하자."}},{"id":"written-2022-1-7","no":7,"unit":"소프트웨어 설계","q":"소프트웨어 개발에 이용되는 모델(Model)에 대한 설명 중 거리가 먼 것은?","choices":["모델은 개발 대상을 추상화하고 기호나 그림 등으로 시각적으로 표현한다.","모델을 통해 소프트웨어에 대한 이해도를 향상시킬 수 있\n다.","모델을 통해 이해 당사자 간의 의사소통이 향상된다.","모델을 통해 향후 개발될 시스템의 유추는 불가능하다."],"ans":4,"rate":93,"exp":{"concept":"모델은 만들 시스템을 단순하게 줄여서(추상화) 그림이나 기호로 보여 주는 설계도다. 모델을 보면 시스템을 더 잘 이해하고, 관계자끼리 의사소통이 쉬워지며, 앞으로 만들어질 시스템의 모습을 미리 짐작할 수 있다. 건물을 짓기 전에 만드는 모형과 같다.","choices":[{"verdict":"오답","why":"모델은 개발 대상을 추상화해 기호나 그림으로 시각적으로 표현한 것이다. 맞는 설명이다."},{"verdict":"오답","why":"모델을 통해 개발할 소프트웨어를 더 잘 이해할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"모델은 개발자·고객 등 이해 당사자 사이의 의사소통을 돕는다. 맞는 설명이다."},{"verdict":"정답","why":"모델을 만드는 주된 목적 중 하나가 앞으로 개발될 시스템의 모습을 미리 유추하는 것이다. 유추가 불가능하다는 설명은 틀렸다."}],"keywords":[{"term":"모델(Model)","desc":"개발 대상을 추상화해 기호·그림으로 시각화한 것"},{"term":"모델링 언어","desc":"모델을 표현하는 표준 표기법, 대표적으로 UML"}],"memo":"모형을 만드는 이유는 미리 보기 위해서다. '유추 불가능'이라는 말이 나오면 틀린 보기다."}},{"id":"written-2022-1-8","no":8,"unit":"소프트웨어 설계","q":"다음의 설명에 해당하는 언어는?\n<img src=\"data/img/eip_written_20220305_008.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["JAVA","C","UML","Python"],"ans":3,"rate":75,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"},{"title":"파이썬","url":"https://itwiki.kr/w/파이썬"}],"exp":{"concept":"UML(Unified Modeling Language)은 객체지향 시스템을 만들 때 산출물을 그림으로 표현하는 표준 모델링 언어다. 프로그램을 실행하는 프로그래밍 언어가 아니라, 분석가·설계자·개발자가 같은 그림을 보며 소통하기 위한 공통 표기법이다. 지문의 '개발 방법론이나 프로세스가 아니라 표준화된 모델링 언어'가 결정적 단서다.","choices":[{"verdict":"오답","why":"JAVA는 객체지향 프로그래밍 언어로, 실제로 실행되는 프로그램을 작성하는 데 쓰인다. 모델링 언어가 아니다."},{"verdict":"오답","why":"C는 절차적 프로그래밍 언어로, 시스템 프로그래밍 등에 쓰인다. 모델링 언어가 아니다."},{"verdict":"정답","why":"UML은 객체지향 시스템의 산출물을 명세·시각화·문서화하는 표준 모델링 언어다."},{"verdict":"오답","why":"Python은 인터프리터 방식의 프로그래밍 언어다. 모델링 언어가 아니다."}],"keywords":[{"term":"UML","desc":"객체지향 시스템을 시각화·명세·문서화하는 표준 모델링 언어"},{"term":"UML 구성 요소","desc":"사물(Things), 관계(Relationships), 다이어그램(Diagrams)"},{"term":"OMG","desc":"UML을 표준으로 관리하는 단체(Object Management Group)"}],"memo":"지문에 '모델링 언어', '시각화', '명세화·문서화'가 보이면 UML이다."}},{"id":"written-2022-1-9","no":9,"unit":"소프트웨어 설계","q":"다음 내용이 설명하는 UI설계 도구는?\n<img src=\"data/img/eip_written_20220305_009.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["스토리보드(Storyboard)","목업(Mockup)","프로토타입(Prototype)","유스케이스(Usecase)"],"ans":2,"rate":69,"wiki":[{"title":"스토리보드","url":"https://itwiki.kr/w/스토리보드"},{"title":"목업","url":"https://itwiki.kr/w/목업"},{"title":"프로토타입","url":"https://itwiki.kr/w/프로토타입"},{"title":"유스케이스","url":"https://itwiki.kr/w/유스케이스"}],"exp":{"concept":"UI 설계 도구에는 와이어프레임, 스토리보드, 목업, 프로토타입, 유스케이스 등이 있다. 그중 목업(Mockup)은 실제 화면과 거의 똑같이 보이게 만든 정적인 모형으로, 겉모양만 보여 줄 뿐 실제로 동작하지는 않는다. 가게 앞에 진열된 음식 모형처럼 진짜와 똑같이 생겼지만 먹을 수는 없는 것과 같다.","choices":[{"verdict":"오답","why":"스토리보드(Storyboard)는 화면 설계, 정책, 프로세스, 기능 설명 등을 한데 모은 설계 문서로, 디자이너와 개발자가 최종적으로 참고하는 산출물이다."},{"verdict":"정답","why":"목업(Mockup)은 실제 화면과 유사하게 만든 정적인 모형으로, 시각적으로만 구성 요소를 배치하고 실제로 구현되지는 않는다. 지문과 일치한다."},{"verdict":"오답","why":"프로토타입(Prototype)은 사용자와 상호작용하며 실제처럼 동작해 볼 수 있는 견본이다. 정적인 형태가 아니라 동적인 형태다."},{"verdict":"오답","why":"유스케이스(Usecase)는 사용자 관점에서 시스템이 제공할 기능을 표현하는 모델로, 화면을 그리는 도구가 아니다."}],"keywords":[{"term":"와이어프레임(Wireframe)","desc":"화면 레이아웃을 선으로 대략 그린 뼈대"},{"term":"목업(Mockup)","desc":"실제 화면처럼 보이는 정적 모형, 동작하지 않음"},{"term":"스토리보드(Storyboard)","desc":"화면·정책·프로세스·기능 설명을 담은 최종 설계 문서"},{"term":"프로토타입(Prototype)","desc":"실제처럼 동작해 볼 수 있는 동적 견본"}],"memo":"'정적', '실제로 구현되지 않음'이면 목업, '동적', '상호작용'이면 프로토타입."}},{"id":"written-2022-1-10","no":10,"unit":"소프트웨어 설계","q":"애자일(Agile) 기법 중 스크럼(Scrum)과 관련된 용어에 대한 설명이 틀린 것은?","choices":["스크럼 마스터(Scrum Master)는 스크럼 프로세스를 따르고, 팀이 스크럼을 효과적으로 활용할 수 있도록 보장하는 역할 등을 맡는다.","제품 백로그(Product Backlog)는 스크럼 팀이 해결해야 하는 목록으로 소프트웨어 요구사항, 아키텍처 정의 등이 포함될 수 있다.","스프린트(Sprint)는 하나의 완성된 최종 결과물을 만들기 위한 주기로 3달 이상의 장기간으로 결정된다.","속도(Velocity)는 한 번의 스프린트에서 한 팀이 어느 정도의 제품 백로그를 감당할 수 있는지에 대한 추정치로 볼 수 있다."],"ans":3,"rate":84,"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"},{"title":"스크럼","url":"https://itwiki.kr/w/스크럼"}],"exp":{"concept":"스크럼(Scrum)은 팀이 짧은 기간 단위(스프린트)로 일을 나눠 반복 개발하는 애자일 방법이다. 스프린트는 보통 2~4주 정도의 짧은 기간으로 잡고, 한 번의 스프린트마다 동작하는 결과물을 만들어 낸다. 긴 마라톤을 짧은 구간 달리기로 나눠 뛰는 것과 비슷하다.","choices":[{"verdict":"오답","why":"스크럼 마스터(Scrum Master)는 팀이 스크럼 절차를 잘 따르도록 돕고 방해 요소를 없애 주는 사람이다. 맞는 설명이다."},{"verdict":"오답","why":"제품 백로그(Product Backlog)는 제품에 필요한 요구사항을 우선순위에 따라 나열한 목록이며, 요구사항이나 아키텍처 정의 등이 들어갈 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"스프린트(Sprint)는 보통 2~4주의 짧은 반복 개발 주기다. 3달 이상의 장기간으로 정한다는 설명은 틀렸다."},{"verdict":"오답","why":"속도(Velocity)는 한 스프린트에서 팀이 처리할 수 있는 제품 백로그의 양을 추정한 값이다. 맞는 설명이다."}],"keywords":[{"term":"스프린트(Sprint)","desc":"보통 2~4주의 짧은 반복 개발 주기"},{"term":"제품 백로그(Product Backlog)","desc":"제품 요구사항을 우선순위대로 정리한 목록"},{"term":"스크럼 마스터(Scrum Master)","desc":"팀이 스크럼을 잘 수행하도록 돕는 조력자"},{"term":"속도(Velocity)","desc":"한 스프린트에 팀이 처리할 수 있는 백로그 양의 추정치"}],"memo":"스프린트는 '전력 질주'라는 뜻이다. 3달 넘게 전력 질주할 수는 없다."}},{"id":"written-2022-1-11","no":11,"unit":"소프트웨어 설계","q":"UML 다이어그램 중 정적 다이어그램이 아닌 것은?","choices":["컴포넌트 다이어그램","배치 다이어그램","순차 다이어그램","패키지 다이어그램"],"ans":3,"rate":69,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"},{"title":"배치 다이어그램","url":"https://itwiki.kr/w/배치 다이어그램"},{"title":"패키지 다이어그램","url":"https://itwiki.kr/w/패키지 다이어그램"}],"exp":{"concept":"UML 다이어그램은 시스템의 뼈대(구조)를 보여 주는 정적(구조) 다이어그램과, 시간에 따른 움직임(행위)을 보여 주는 동적(행위) 다이어그램으로 나뉜다. 순차(시퀀스) 다이어그램은 객체들이 시간 순서에 따라 메시지를 주고받는 과정을 보여 주므로 동적 다이어그램이다.","choices":[{"verdict":"오답","why":"컴포넌트 다이어그램은 시스템을 이루는 컴포넌트와 그 사이의 의존 관계를 나타내는 정적(구조) 다이어그램이다."},{"verdict":"오답","why":"배치 다이어그램은 소프트웨어가 어떤 물리적 노드(서버 등)에 배치되는지 나타내는 정적(구조) 다이어그램이다."},{"verdict":"정답","why":"순차(시퀀스) 다이어그램은 객체 간 메시지 교환을 시간 순서로 표현하는 동적(행위) 다이어그램이다. 정적 다이어그램이 아니다."},{"verdict":"오답","why":"패키지 다이어그램은 요소들을 그룹(패키지)으로 묶고 패키지 간 의존 관계를 나타내는 정적(구조) 다이어그램이다."}],"keywords":[{"term":"구조(정적) 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지"},{"term":"행위(동적) 다이어그램","desc":"유스케이스, 시퀀스(순차), 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍"}],"memo":"시간 흐름이나 상태 변화가 들어가면 동적이다. 순차는 '순서'가 있으니 동적."}},{"id":"written-2022-1-12","no":12,"unit":"소프트웨어 설계","q":"LOC기법에 의하여 예측된 총 라인수가 36000라인, 개발에 참여할 프로그래머가 6명, 프로그래머들의 평균 생산성이 월간 300라인일 때 개발에 소요되는 기간을 계산한 결과로 가장 옳은 것은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"rate":89,"wiki":[{"title":"LOC","url":"https://itwiki.kr/w/LOC"}],"exp":{"concept":"LOC(Lines Of Code) 기법은 프로그램의 예상 코드 줄 수로 개발 기간과 비용을 추정한다. 개발 기간은 '총 라인 수 ÷ (프로그래머 수 × 1인당 월 생산성)'으로 구한다. 한 달에 팀 전체가 짤 수 있는 줄 수로 전체 줄 수를 나누는 것이다.","choices":[{"verdict":"오답","why":"5개월이면 6명 × 300라인 × 5개월 = 9,000라인밖에 작성하지 못한다. 36,000라인에 못 미친다."},{"verdict":"오답","why":"10개월이면 6명 × 300라인 × 10개월 = 18,000라인으로, 필요한 양의 절반이다."},{"verdict":"오답","why":"15개월이면 6명 × 300라인 × 15개월 = 27,000라인으로 부족하다."},{"verdict":"정답","why":"팀의 월 생산량은 6명 × 300라인 = 1,800라인이다. 36,000 ÷ 1,800 = 20이므로 20개월이 걸린다."}],"keywords":[{"term":"LOC 기법","desc":"원시 코드 라인 수로 비용·기간을 추정하는 상향식 비용 산정 기법"},{"term":"개발 기간","desc":"총 라인 수 ÷ (인원 × 1인당 월 생산성)"},{"term":"노력(인월)","desc":"총 라인 수 ÷ 1인당 월 생산성, 이 문제에서는 36,000 ÷ 300 = 120인월"}],"memo":"먼저 노력(인월) 120을 구하고 인원 6명으로 나누면 기간 20개월. 인원으로 나누는 걸 잊지 말자."}},{"id":"written-2022-1-13","no":13,"unit":"소프트웨어 설계","q":"클래스 설계원칙에 대한 바른 설명은?","choices":["단일 책임원칙 : 하나의 클래스만 변경 가능 해야한다.","개방-폐쇄의 원칙 : 클래스는 확장에 대해 열려 있어야 하며 변경에 대해 닫혀 있어야 한다.","리스코프 교체의 원칙 : 여러 개의 책임을 가진 클래스는 하나의 책임을 가진 클래스로 대체되어야 한다.","의존관계 역전의 원칙 : 클라이언트는 자신이 사용하는 메소드와 의존관계를 갖지 않도록 해야 한다."],"ans":2,"rate":61,"wiki":[{"title":"객체지향 설계","url":"https://itwiki.kr/w/객체지향 설계"}],"exp":{"concept":"객체지향 설계 원칙 SOLID는 클래스를 바꾸기 쉽고 튼튼하게 만드는 다섯 가지 규칙이다. 그중 개방-폐쇄 원칙(OCP)은 새 기능을 덧붙이는 확장에는 열려 있고, 기존 코드를 고치는 변경에는 닫혀 있어야 한다는 원칙이다. 멀티탭에 플러그를 꽂아 기능을 늘리되 멀티탭 자체를 뜯어고치지는 않는 것과 같다.","choices":[{"verdict":"오답","why":"단일 책임 원칙(SRP)은 하나의 클래스는 하나의 책임만 가져야 한다는 원칙이다. '하나의 클래스만 변경 가능해야 한다'는 잘못된 설명이다."},{"verdict":"정답","why":"개방-폐쇄 원칙(OCP)은 확장에는 열려 있고 변경에는 닫혀 있어야 한다는 원칙이다. 바른 설명이다."},{"verdict":"오답","why":"리스코프 치환 원칙(LSP)은 하위 클래스가 상위 클래스를 대신해도 프로그램이 문제없이 동작해야 한다는 원칙이다. 책임 개수와는 관계없다."},{"verdict":"오답","why":"의존 관계 역전 원칙(DIP)은 변하기 쉬운 구체 클래스가 아니라 추상화(인터페이스)에 의존해야 한다는 원칙이다. 보기는 인터페이스 분리 원칙(ISP, 클라이언트는 자신이 사용하지 않는 메소드와 의존 관계를 맺지 않아야 함)을 비틀어 놓은 문장이다."}],"keywords":[{"term":"SRP","desc":"단일 책임 원칙, 클래스는 하나의 책임만"},{"term":"OCP","desc":"개방-폐쇄 원칙, 확장에는 열리고 변경에는 닫힘"},{"term":"LSP","desc":"리스코프 치환 원칙, 하위 클래스는 상위 클래스를 대체할 수 있어야 함"},{"term":"ISP","desc":"인터페이스 분리 원칙, 사용하지 않는 메소드에 의존하지 않음"},{"term":"DIP","desc":"의존 관계 역전 원칙, 구체 클래스가 아닌 추상화에 의존"}],"memo":"SOLID 다섯 글자 순서대로 S-단일 책임, O-개방폐쇄, L-리스코프, I-인터페이스 분리, D-의존 역전."}},{"id":"written-2022-1-14","no":14,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴에서 생성(Creational) 패턴에 해당하는 것은?","choices":["컴퍼지트(Composite)","어댑터(Adapter)","추상 팩토리(Abstract Factory)","옵서버(Observer)"],"ans":3,"rate":66,"exp":{"concept":"GoF 디자인 패턴 23가지는 목적에 따라 생성, 구조, 행위 패턴으로 나뉜다. 생성 패턴은 객체를 어떻게 만들지를 다루며, 추상 팩토리(Abstract Factory)는 서로 관련된 객체들을 구체 클래스를 지정하지 않고 한꺼번에 만들어 주는 생성 패턴이다.","choices":[{"verdict":"오답","why":"컴퍼지트(Composite)는 객체들을 트리 구조로 묶어 부분과 전체를 같은 방식으로 다루게 하는 구조 패턴이다."},{"verdict":"오답","why":"어댑터(Adapter)는 호환되지 않는 인터페이스를 맞춰 함께 동작하게 하는 구조 패턴이다."},{"verdict":"정답","why":"추상 팩토리(Abstract Factory)는 관련 객체들의 묶음을 구체 클래스에 의존하지 않고 생성하는 생성 패턴이다."},{"verdict":"오답","why":"옵서버(Observer)는 한 객체의 상태가 바뀌면 의존하는 객체들에게 자동으로 알려 주는 행위 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤"},{"term":"구조 패턴","desc":"어댑터, 브리지, 컴퍼지트, 데코레이터, 퍼사드, 플라이웨이트, 프록시"},{"term":"행위 패턴","desc":"옵서버, 전략, 커맨드, 상태, 템플릿 메소드, 반복자, 방문자 등"}],"memo":"생성 패턴은 이름에 '만드는' 느낌이 있다: 팩토리(공장), 빌더(건축가), 프로토타입(원형 복제), 싱글톤(하나만 생성)."}},{"id":"written-2022-1-15","no":15,"unit":"소프트웨어 설계","q":"아키텍처 설계과정이 올바른 순서로 나열된 것은?\n<img src=\"data/img/eip_written_20220305_015.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉮ → ㉯ → ㉰ → ㉱ → ㉲","㉲ → ㉮ → ㉯ → ㉱ → ㉰","㉮ → ㉲ → ㉯ → ㉱ → ㉰","㉮ → ㉯ → ㉰ → ㉲ → ㉱"],"ans":1,"rate":64,"exp":{"concept":"아키텍처 설계는 먼저 무엇을 달성할지(설계 목표)를 정한 뒤, 어떤 종류의 시스템인지(시스템 타입) 결정하고, 그에 맞는 아키텍처 스타일을 적용·조정한다. 그다음 서브시스템의 기능과 인터페이스 동작을 작성하고, 마지막으로 전체 설계를 검토한다. 집을 지을 때 목적 → 건물 종류 → 양식 선택 → 방별 설계 → 최종 점검 순서로 가는 것과 같다.","choices":[{"verdict":"정답","why":"설계 목표 설정 → 시스템 타입 결정 → 스타일 적용 및 커스터마이즈 → 서브시스템의 기능·인터페이스 동작 작성 → 아키텍처 설계 검토 순서로, 올바른 순서다."},{"verdict":"오답","why":"아키텍처 설계 검토(㉲)는 설계를 다 마친 뒤 마지막에 하는 단계이므로 처음에 올 수 없다."},{"verdict":"오답","why":"검토(㉲)가 두 번째에 오고 서브시스템 작성(㉱)이 스타일 적용(㉰)보다 앞서 있어 순서가 맞지 않는다."},{"verdict":"오답","why":"검토(㉲)를 서브시스템 작성(㉱)보다 먼저 할 수는 없다. 검토는 마지막 단계다."}],"keywords":[{"term":"아키텍처 설계 과정","desc":"설계 목표 설정 → 시스템 타입 결정 → 스타일 적용 및 커스터마이즈 → 서브시스템 기능·인터페이스 작성 → 설계 검토"},{"term":"아키텍처 스타일(패턴)","desc":"레이어, 클라이언트-서버, 파이프-필터, MVC, 마스터-슬레이브 등"}],"memo":"목표 → 타입 → 스타일 → 서브시스템 → 검토. 검토는 언제나 맨 마지막이다."}},{"id":"written-2022-1-16","no":16,"unit":"소프트웨어 설계","q":"사용자 인터페이스를 설계할 경우 고려해야 할 가이드라인과 가장 거리가 먼 것은?","choices":["심미성을 사용성보다 우선하여 설계해야 한다.","효율성을 높이게 설계해야 한다.","발생하는 오류를 쉽게 수정할 수 있어야 한다.","사용자에게 피드백을 제공해야 한다."],"ans":1,"rate":90,"wiki":[{"title":"사용자 인터페이스","url":"https://itwiki.kr/w/사용자 인터페이스"}],"exp":{"concept":"사용자 인터페이스(UI)는 보기 좋은 것보다 쓰기 편한 것이 먼저다. 그래서 UI 설계 지침은 사용성을 가장 중요하게 보고, 효율성, 쉬운 오류 수정, 피드백 제공 등을 강조한다. 디자인이 예뻐도 버튼을 찾기 어렵다면 좋은 UI가 아니다.","choices":[{"verdict":"정답","why":"UI 설계에서는 사용성을 심미성(보기 좋음)보다 우선해야 한다. 심미성을 우선한다는 설명은 지침과 거리가 멀다."},{"verdict":"오답","why":"사용자가 원하는 작업을 빠르고 적은 노력으로 할 수 있도록 효율성을 높여야 한다. 올바른 지침이다."},{"verdict":"오답","why":"오류가 났을 때 사용자가 쉽게 원인을 알고 고칠 수 있어야 한다. 올바른 지침이다."},{"verdict":"오답","why":"사용자의 행동에 대해 결과를 알려 주는 피드백을 제공해야 한다. 올바른 지침이다."}],"keywords":[{"term":"UI 설계 지침","desc":"사용자 중심, 일관성, 단순성, 결과 예측 가능, 가시성, 표준화, 접근성, 명확성, 오류 발생 해결"},{"term":"UI 설계 원칙","desc":"직관성, 유효성, 학습성, 유연성"}],"memo":"UI에서 '예쁨'은 '편함'을 이길 수 없다. 심미성 우선이면 오답 보기다."}},{"id":"written-2022-1-17","no":17,"unit":"소프트웨어 설계","q":"소프트웨어 설계에서 자주 발생하는 문제에 대한 일반적이고 반복적인 해결 방법을 무엇이라고 하는가?","choices":["모듈 분해","디자인 패턴","연관 관계","클래스 도출"],"ans":2,"rate":72,"wiki":[{"title":"소프트웨어_모듈화","url":"https://itwiki.kr/w/소프트웨어_모듈화"}],"exp":{"concept":"디자인 패턴은 소프트웨어 설계에서 자주 부딪히는 문제에 대해 검증된 해결 방법을 일반화해 정리한 것이다. 요리 레시피처럼, 같은 종류의 문제가 생기면 처음부터 고민하지 않고 이미 정리된 방법을 가져다 쓸 수 있다.","choices":[{"verdict":"오답","why":"모듈 분해는 시스템을 기능 단위의 모듈로 나누는 작업으로, 반복되는 문제의 일반적 해결책을 가리키는 말이 아니다."},{"verdict":"정답","why":"디자인 패턴은 자주 발생하는 설계 문제에 대한 일반적이고 반복적으로 쓸 수 있는 해결 방법이다."},{"verdict":"오답","why":"연관 관계는 UML에서 클래스(사물)들이 서로 관련되어 있음을 나타내는 관계다."},{"verdict":"오답","why":"클래스 도출은 요구사항에서 클래스를 찾아내는 분석 활동이다."}],"keywords":[{"term":"디자인 패턴","desc":"자주 발생하는 설계 문제에 대한 재사용 가능한 해결책"},{"term":"GoF 디자인 패턴","desc":"에릭 감마 등 네 명이 정리한 23가지 패턴(생성 5, 구조 7, 행위 11)"}],"memo":"'자주 발생하는 문제의 일반적·반복적 해결 방법'이라는 표현은 디자인 패턴의 정의 그 자체다."}},{"id":"written-2022-1-18","no":18,"unit":"소프트웨어 설계","q":"객체지향 분석기법의 하나로 객체 모형, 동적 모형, 기능 모형의 3개 모형을 생성하는 방법은?","choices":["Wirfs-Block Method","Rumbaugh Method","Booch Method","Jacobson Method"],"ans":2,"rate":84,"exp":{"concept":"럼바우(Rumbaugh)의 OMT(Object Modeling Technique)는 객체지향 분석을 세 가지 모델로 나눠 진행한다. 객체 모델링(객체와 관계를 객체 다이어그램으로), 동적 모델링(시간에 따른 상태 변화를 상태 다이어그램으로), 기능 모델링(데이터 흐름을 자료 흐름도로) 순서로 모델을 만든다.","choices":[{"verdict":"오답","why":"Wirfs-Brock(보기의 Block은 Brock의 오기) 방법은 분석과 설계를 구분하지 않고, 고객 명세서를 평가해 설계까지 연속적으로 수행하는 책임 중심 방법이다."},{"verdict":"정답","why":"Rumbaugh 방법(OMT)은 객체 모형, 동적 모형, 기능 모형의 세 가지 모델을 만든다."},{"verdict":"오답","why":"Booch 방법은 미시적·거시적 개발 프로세스를 모두 사용하며 클래스와 객체를 분석·식별하는 방법이다."},{"verdict":"오답","why":"Jacobson 방법은 유스케이스(Use Case)를 강조해 사용자 관점에서 분석하는 방법이다."}],"keywords":[{"term":"럼바우 OMT","desc":"객체 모델링 → 동적 모델링 → 기능 모델링"},{"term":"객체 모델링","desc":"객체 다이어그램으로 객체·관계 표현"},{"term":"동적 모델링","desc":"상태 다이어그램으로 시간에 따른 변화 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)로 데이터 처리 흐름 표현"}],"memo":"럼바우는 '객동기'(객체-동적-기능) 순서로 외운다."}},{"id":"written-2022-1-19","no":19,"unit":"소프트웨어 설계","q":"입력되는 데이터를 컴퓨터의 프로세서가 처리하기 전에 미리 처리하여 프로세서가 처리하는 시간을 줄여주는 프로그램이나 하드웨어를 말하는 것은?","choices":["EAI","FEP","GPL","Duplexing"],"ans":2,"rate":53,"wiki":[{"title":"EAI","url":"https://itwiki.kr/w/EAI"},{"title":"FEP","url":"https://itwiki.kr/w/FEP"}],"exp":{"concept":"전처리기(FEP, Front-End Processor)는 입력 데이터를 메인 프로세서가 처리하기 전에 미리 처리해 주는 프로그램이나 하드웨어다. 통신 제어나 데이터 정리 같은 앞단 작업을 대신 맡아 프로세서의 처리 시간을 줄여 준다. 식당에서 손질 담당이 재료를 미리 다듬어 두면 요리사가 바로 조리할 수 있는 것과 같다.","choices":[{"verdict":"오답","why":"EAI(Enterprise Application Integration)는 기업 내 여러 애플리케이션을 연계·통합하는 솔루션이다."},{"verdict":"정답","why":"FEP(Front-End Processor)는 입력 데이터를 프로세서가 처리하기 전에 미리 처리해 처리 시간을 줄여 주는 프로그램이나 하드웨어다."},{"verdict":"오답","why":"GPL(GNU General Public License)은 자유 소프트웨어 재단이 만든 오픈 소스 소프트웨어 라이선스다."},{"verdict":"오답","why":"Duplexing은 장치나 통신 경로를 이중으로 구성하거나 양방향으로 전송하는 것을 가리키는 말로, 데이터를 미리 처리하는 장치가 아니다."}],"keywords":[{"term":"FEP(Front-End Processor)","desc":"입력 데이터를 미리 처리해 메인 프로세서의 부담을 줄이는 전처리기"},{"term":"EAI","desc":"기업 내 애플리케이션 간 연계·통합 솔루션"},{"term":"GPL","desc":"GNU 일반 공중 사용 허가서, 오픈 소스 라이선스"}],"memo":"Front-End는 '앞단'이다. 앞에서 미리 처리하면 FEP."}},{"id":"written-2022-1-20","no":20,"unit":"소프트웨어 설계","q":"객체 지향 개념 중 하나 이상의 유사한 객체들을 묶어 공통된 특성을 표현한 데이터 추상화를 의미하는 것은?","choices":["Method","Class","Field","Message"],"ans":2,"rate":88,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"클래스(Class)는 비슷한 객체들의 공통된 속성과 행동을 뽑아 하나로 묶은 틀이다. 붕어빵 틀이 클래스라면, 틀로 찍어 낸 붕어빵 하나하나가 객체(인스턴스)다. 공통 특성을 묶어 표현했으므로 데이터 추상화라고 한다.","choices":[{"verdict":"오답","why":"Method(메소드)는 객체가 수행하는 동작, 즉 클래스 안에 정의된 함수다."},{"verdict":"정답","why":"Class(클래스)는 유사한 객체들을 묶어 공통된 속성과 연산을 표현한 데이터 추상화다."},{"verdict":"오답","why":"Field(필드)는 클래스 안에서 객체의 상태를 저장하는 변수(속성)다."},{"verdict":"오답","why":"Message(메시지)는 객체에게 어떤 동작을 하라고 요청하는 수단이다."}],"keywords":[{"term":"클래스(Class)","desc":"공통 속성·연산을 가진 객체들의 틀, 데이터 추상화"},{"term":"객체(Object)","desc":"클래스로부터 만들어진 실체, 인스턴스"},{"term":"메시지(Message)","desc":"객체에게 메소드 수행을 요청하는 것"}],"memo":"붕어빵 틀은 클래스, 붕어빵은 객체. '묶어서 공통 특성'이면 클래스다."}},{"id":"written-2022-1-21","no":21,"unit":"소프트웨어 개발","q":"클린 코드(Clean Code)를 작성하기 위한 원칙으로 틀린 것은?","choices":["추상화 : 하위 클래스/메소드/함수를 통해 애플리케이션의 특성을 간략하게 나타내고, 상세 내용은 상위 클래스/메소드/함수에서 구현한다.","의존성 : 다른 모듈에 미치는 영향을 최소화하도록 작성한다.","가독성 : 누구든지 읽기 쉽게 코드를 작성한다.","중복성 : 중복을 최소화 할 수 있는 코드를 작성한다."],"ans":1,"rate":77,"wiki":[{"title":"클린 코드","url":"https://itwiki.kr/w/클린 코드"}],"exp":{"concept":"클린 코드는 누가 읽어도 이해하기 쉽고 고치기 쉬운 코드다. 클린 코드 원칙 중 추상화는 상위 클래스·메소드·함수에서 애플리케이션의 특성을 간략히 드러내고, 자세한 내용은 하위 클래스·메소드·함수에서 구현하는 것이다. 책의 목차(상위)와 본문(하위)의 관계와 같다.","choices":[{"verdict":"정답","why":"추상화 원칙은 상위 클래스·메소드·함수에서 특성을 간략하게 나타내고 상세 내용은 하위에서 구현하는 것이다. 보기는 상위와 하위를 뒤바꿔 놓았으므로 틀렸다."},{"verdict":"오답","why":"의존성 원칙: 다른 모듈에 미치는 영향을 최소화하도록 작성한다. 맞는 설명이다."},{"verdict":"오답","why":"가독성 원칙: 누구든지 읽기 쉽게 코드를 작성한다. 맞는 설명이다."},{"verdict":"오답","why":"중복성 원칙: 중복을 최소화하는 코드를 작성한다. 맞는 설명이다."}],"keywords":[{"term":"클린 코드 원칙","desc":"가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화"},{"term":"추상화 원칙","desc":"상위에서 간략하게, 하위에서 상세하게 구현"}],"memo":"목차는 위에, 본문은 아래에. '하위에서 간략, 상위에서 상세'면 거꾸로 된 보기다."}},{"id":"written-2022-1-22","no":22,"unit":"소프트웨어 개발","q":"단위 테스트에서 테스트의 대상이 되는 하위 모듈을 호출하고, 파라미터를 전달하는 가상의 모듈로 상향식 테스트에 필요한 것은?","choices":["테스트 스텁(Test Stub)","테스트 드라이버(Test Driver)","테스트 슈트(Test Suites)","테스트 케이스(Test Case)"],"ans":2,"rate":67,"wiki":[{"title":"단위 테스트","url":"https://itwiki.kr/w/단위 테스트"},{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"통합 테스트를 할 때 아직 만들어지지 않은 모듈은 가짜 모듈로 대신한다. 상향식 테스트는 아래 모듈부터 시험하므로, 그 모듈을 불러 주고 값을 넘겨 줄 '윗사람' 역할의 가짜 모듈이 필요한데 이것이 테스트 드라이버다. 반대로 하향식 테스트에서 아직 없는 아래 모듈을 대신하는 것은 테스트 스텁이다.","choices":[{"verdict":"오답","why":"테스트 스텁(Test Stub)은 하향식 테스트에서 아직 없는 하위 모듈을 대신하는 가상 모듈이다. 하위 모듈을 호출하는 쪽이 아니다."},{"verdict":"정답","why":"테스트 드라이버(Test Driver)는 테스트 대상 하위 모듈을 호출하고 파라미터를 전달하는 가상 모듈로, 상향식 테스트에 필요하다."},{"verdict":"오답","why":"테스트 슈트(Test Suites)는 여러 테스트 케이스를 목적에 따라 묶어 놓은 집합이다."},{"verdict":"오답","why":"테스트 케이스(Test Case)는 입력값, 실행 조건, 기대 결과를 정리한 테스트 항목 명세다."}],"keywords":[{"term":"테스트 드라이버","desc":"상향식 통합 테스트용, 하위 모듈을 호출하는 가상의 상위 모듈"},{"term":"테스트 스텁","desc":"하향식 통합 테스트용, 호출당하는 가상의 하위 모듈"},{"term":"테스트 슈트","desc":"테스트 케이스들의 묶음"}],"memo":"상향식-드라이버, 하향식-스텁. 운전자(Driver)는 위에서 조종한다고 기억하자."}},{"id":"written-2022-1-23","no":23,"unit":"소프트웨어 개발","q":"스택(Stack)에 대한 옳은 내용으로만 나열된 것은?\n<img src=\"data/img/eip_written_20220305_023.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠, ㉡","㉡, ㉢","㉣","㉠, ㉡, ㉢, ㉣"],"ans":3,"rate":71,"wiki":[{"title":"스택","url":"https://itwiki.kr/w/스택"},{"title":"선형_자료_구조","url":"https://itwiki.kr/w/선형_자료_구조"}],"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)에서만 넣고 빼는 자료 구조로, 나중에 들어간 것이 먼저 나오는 LIFO(Last In First Out) 방식이다. 함수를 호출하면 돌아올 주소를 쌓아 두었다가 끝나면 거꾸로 꺼내야 하므로 인터럽트 처리와 서브루틴 호출에 쓰인다. 접시를 쌓고 맨 위부터 꺼내는 것과 같다. ㉠과 ㉡은 큐, ㉢은 데크에 대한 설명이다.","choices":[{"verdict":"오답","why":"㉠ FIFO는 먼저 들어간 것이 먼저 나오는 큐(Queue)의 방식이고, ㉡ 뒤(Rear)로 넣고 앞(Front)으로 빼는 것도 큐의 구조다. 스택이 아니다."},{"verdict":"오답","why":"㉡은 큐의 구조, ㉢ 양쪽 끝에서 삽입·삭제가 모두 되는 것은 데크(Deque)다. 스택이 아니다."},{"verdict":"정답","why":"㉣ 인터럽트 처리와 서브루틴 호출은 복귀 주소를 LIFO로 저장해야 하므로 스택의 대표 응용이다. 옳은 내용은 ㉣ 하나뿐이다."},{"verdict":"오답","why":"㉠·㉡은 큐, ㉢은 데크에 대한 설명이므로 전부 고를 수 없다."}],"keywords":[{"term":"스택(Stack)","desc":"LIFO, Top 한쪽에서만 삽입(push)·삭제(pop)"},{"term":"큐(Queue)","desc":"FIFO, Rear에서 삽입하고 Front에서 삭제"},{"term":"데크(Deque)","desc":"양쪽 끝에서 삽입·삭제가 모두 가능"},{"term":"스택 응용","desc":"서브루틴 호출, 인터럽트 처리, 수식 계산(후위 표기), 깊이 우선 탐색"}],"memo":"FIFO·Front·Rear가 보이면 큐, 양쪽 끝이면 데크, 서브루틴·인터럽트면 스택."}},{"id":"written-2022-1-24","no":24,"unit":"소프트웨어 개발","q":"소프트웨어 모듈화의 장점이 아닌 것은?","choices":["오류의 파급 효과를 최소화한다.","기능의 분리가 가능하여 인터페이스가 복잡하다.","모듈의 재사용 가능으로 개발과 유지보수가 용이하다.","프로그램의 효율적인 관리가 가능하다."],"ans":2,"rate":95,"wiki":[{"title":"소프트웨어_모듈화","url":"https://itwiki.kr/w/소프트웨어_모듈화"}],"exp":{"concept":"모듈화는 큰 프로그램을 기능별로 작은 모듈로 나누는 것이다. 나누어 두면 한 모듈의 오류가 다른 곳으로 덜 퍼지고, 모듈을 재사용할 수 있으며, 관리와 유지보수가 쉬워진다. 기능을 잘 나누면 모듈 사이의 인터페이스는 오히려 단순해진다.","choices":[{"verdict":"오답","why":"오류가 해당 모듈 안에 머물러 다른 부분으로 퍼지는 파급 효과가 줄어든다. 모듈화의 장점이다."},{"verdict":"정답","why":"모듈화를 하면 기능이 분리되어 인터페이스가 단순해진다. 인터페이스가 복잡해진다는 것은 장점이 아니며 틀린 설명이다."},{"verdict":"오답","why":"모듈을 재사용할 수 있어 개발과 유지보수가 쉬워진다. 모듈화의 장점이다."},{"verdict":"오답","why":"프로그램을 작은 단위로 나눠 효율적으로 관리할 수 있다. 모듈화의 장점이다."}],"keywords":[{"term":"모듈화(Modularity)","desc":"프로그램을 기능 단위의 모듈로 나누는 것"},{"term":"좋은 모듈","desc":"결합도는 낮게, 응집도는 높게"}],"memo":"장점을 묻는 문제에서 '복잡하다'는 말이 들어가면 걸러 내자."}},{"id":"written-2022-1-25","no":25,"unit":"소프트웨어 개발","q":"소프트웨어 프로젝트 관리에 대한 설명으로 가장 옳은 것은?","choices":["개발에 따른 산출물 관리","소요인력은 최대화하되 정책 결정은 신속하게 처리","주어진 기간은 연장하되 최소의 비용으로 시스템을 개발","주어진 기간 내에 최소의 비용으로 사용자를 만족시키는 시스템을 개발"],"ans":4,"rate":72,"wiki":[{"title":"프로젝트","url":"https://itwiki.kr/w/프로젝트"},{"title":"프로젝트 관리","url":"https://itwiki.kr/w/프로젝트 관리"}],"exp":{"concept":"소프트웨어 프로젝트 관리는 주어진 기간 안에, 최소의 비용으로, 사용자를 만족시키는 시스템을 개발하도록 계획하고 감독하는 활동이다. 일정, 비용, 품질 세 가지를 모두 지키는 것이 목표다.","choices":[{"verdict":"오답","why":"산출물 관리는 형상 관리 같은 프로젝트 관리의 일부 활동일 뿐, 프로젝트 관리 전체를 설명하는 말로는 부족하다."},{"verdict":"오답","why":"소요 인력은 최대화가 아니라 적정하게, 효율적으로 운용해야 한다."},{"verdict":"오답","why":"기간을 연장하는 것은 프로젝트 관리의 목표가 아니다. 주어진 기간 안에 끝내야 한다."},{"verdict":"정답","why":"주어진 기간 내에 최소의 비용으로 사용자를 만족시키는 시스템을 개발하는 것이 프로젝트 관리의 목표다."}],"keywords":[{"term":"프로젝트 관리 3P","desc":"사람(People), 문제(Problem), 프로세스(Process)"},{"term":"프로젝트 관리 대상","desc":"일정 관리, 비용 관리, 품질 관리, 위험 관리 등"}],"memo":"기간 내, 최소 비용, 사용자 만족. 셋 중 하나라도 어기면 오답이다."}},{"id":"written-2022-1-26","no":26,"unit":"소프트웨어 개발","q":"정형 기술 검토(FTR)의 지침으로 틀린 것은?","choices":["의제를 제한한다.","논쟁과 반박을 제한한다.","문제 영역을 명확히 표현한다.","참가자의 수를 제한하지 않는다."],"ans":4,"rate":71,"wiki":[{"title":"정형 기술 검토","url":"https://itwiki.kr/w/정형 기술 검토"}],"exp":{"concept":"정형 기술 검토(FTR, Formal Technical Review)는 소프트웨어 산출물의 오류를 찾기 위해 여러 사람이 공식적으로 모여 검토하는 회의다. 회의가 길어지거나 산만해지지 않도록 의제와 참가자 수를 제한하고, 논쟁은 줄이며, 해결책보다 문제를 찾는 데 집중한다.","choices":[{"verdict":"오답","why":"의제를 제한해 회의가 산만해지지 않게 한다. FTR 지침에 맞는다."},{"verdict":"오답","why":"논쟁과 반박을 제한해 시간을 아낀다. FTR 지침에 맞는다."},{"verdict":"오답","why":"문제 영역을 명확히 표현한다. FTR 지침에 맞는다."},{"verdict":"정답","why":"FTR은 효율을 위해 참가자의 수를 제한한다. 제한하지 않는다는 것은 틀린 설명이다."}],"keywords":[{"term":"FTR 지침","desc":"의제 제한, 참가자 수 제한, 논쟁·반박 제한, 문제 영역 명확화, 해결책보다 문제 지적, 사전 준비, 체크리스트 사용"},{"term":"FTR 종류","desc":"검토 회의(Walkthrough), 검열(Inspection)"}],"memo":"FTR 지침은 거의 다 '제한'이다. 무언가를 '제한하지 않는다'는 보기가 답이다."}},{"id":"written-2022-1-27","no":27,"unit":"소프트웨어 개발","q":"소프트웨어 재공학의 주요 활동 중 기존 소프트웨어 시스템을 새로운 기술 또는 하드웨어 환경에서 사용할 수 있도록 변환하는 작업을 의미하는 것은?","choices":["Analysis","Migration","Restructuring","Reverse Engineering"],"ans":2,"rate":56,"wiki":[{"title":"소프트웨어 재공학","url":"https://itwiki.kr/w/소프트웨어 재공학"}],"exp":{"concept":"소프트웨어 재공학(Re-engineering)은 기존 소프트웨어를 버리지 않고 고쳐서 다시 쓰는 것이다. 주요 활동은 분석, 재구성, 역공학, 이식(Migration)이다. 그중 이식은 기존 소프트웨어를 새로운 기술이나 하드웨어 환경에서 쓸 수 있게 옮기는 작업이다. 오래된 게임을 새 게임기에서 돌아가게 옮기는 것과 비슷하다.","choices":[{"verdict":"오답","why":"Analysis(분석)는 기존 소프트웨어의 명세서를 확인해 동작을 이해하고 재공학 대상을 선정하는 활동이다."},{"verdict":"정답","why":"Migration(이식)은 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서 사용할 수 있도록 변환하는 활동이다."},{"verdict":"오답","why":"Restructuring(재구성)은 소프트웨어의 기능과 외부 동작은 바꾸지 않고 내부 구조(코드)를 재조정하는 활동이다."},{"verdict":"오답","why":"Reverse Engineering(역공학)은 기존 코드나 데이터에서 설계·명세 정보를 거꾸로 추출해 내는 활동이다."}],"keywords":[{"term":"재공학 주요 활동","desc":"분석(Analysis), 재구성(Restructuring), 역공학(Reverse Engineering), 이식(Migration)"},{"term":"이식(Migration)","desc":"새로운 기술·하드웨어 환경에서 쓸 수 있게 변환"},{"term":"역공학(Reverse Engineering)","desc":"코드에서 설계 정보를 거꾸로 추출"}],"memo":"Migration은 '이주'다. 다른 환경으로 옮겨 가면 이식."}},{"id":"written-2022-1-28","no":28,"unit":"소프트웨어 개발","q":"정보시스템 개발 단계에서 프로그래밍 언어 선택 시 고려할 사항으로 가장 거리가 먼 것은?","choices":["개발 정보시스템의 특성","사용자의 요구사항","컴파일러의 가용성","컴파일러의 독창성"],"ans":4,"rate":85,"exp":{"concept":"프로그래밍 언어를 고를 때는 만들 시스템의 특성, 사용자 요구사항, 그 언어의 컴파일러를 쓸 수 있는지(가용성), 개발자의 숙련도 같은 현실적인 조건을 따진다. 컴파일러가 얼마나 독창적인지는 개발 결과와 관계가 없다.","choices":[{"verdict":"오답","why":"개발할 정보시스템의 특성(웹, 임베디드, 과학 계산 등)에 맞는 언어를 골라야 한다. 고려 사항이다."},{"verdict":"오답","why":"사용자의 요구사항을 충족할 수 있는 언어여야 한다. 고려 사항이다."},{"verdict":"오답","why":"해당 언어의 컴파일러를 개발 환경에서 사용할 수 있는지(가용성)를 따져야 한다. 고려 사항이다."},{"verdict":"정답","why":"컴파일러의 독창성은 언어 선택에 영향을 주는 요소가 아니다. 고려 사항과 거리가 멀다."}],"keywords":[{"term":"언어 선택 기준","desc":"시스템 특성, 사용자 요구, 컴파일러 가용성, 개발자 경험·숙련도, 성능, 이식성"},{"term":"가용성(Availability)","desc":"필요할 때 실제로 사용할 수 있는 정도"}],"memo":"'독창성'처럼 실무와 관계없는 말이 섞여 있으면 거리가 먼 보기다."}},{"id":"written-2022-1-29","no":29,"unit":"소프트웨어 개발","q":"소프트웨어 패키징에 대한 설명으로 틀린 것은?","choices":["패키징은 개발자 중심으로 진행한다.","신규 및 변경 개발소스를 식별하고, 이를 모듈화하여 상용제품으로 패키징한다.","고객의 편의성을 위해 매뉴얼 및 버전관리를 지속적으로 한다.","범용 환경에서 사용이 가능하도록 일반적인 배포 형태로 패키징이 진행된다."],"ans":1,"rate":89,"wiki":[{"title":"소프트웨어 패키징","url":"https://itwiki.kr/w/소프트웨어 패키징"}],"exp":{"concept":"소프트웨어 패키징은 개발이 끝난 소프트웨어를 고객이 설치해서 쓸 수 있는 형태로 묶는 일이다. 쓰는 사람이 고객이므로 사용자 중심으로 진행하며, 일반적인 배포 형태로 만들고, 매뉴얼과 버전 관리를 계속해 준다.","choices":[{"verdict":"정답","why":"소프트웨어 패키징은 개발자가 아니라 사용자(고객) 중심으로 진행해야 한다. 틀린 설명이다."},{"verdict":"오답","why":"신규 및 변경된 개발 소스를 식별하고 모듈화해 상용 제품으로 패키징한다. 맞는 설명이다."},{"verdict":"오답","why":"고객의 편의를 위해 매뉴얼을 제공하고 버전 관리를 지속적으로 한다. 맞는 설명이다."},{"verdict":"오답","why":"범용 환경에서 쓸 수 있도록 일반적인 배포 형태로 패키징한다. 맞는 설명이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"개발된 소프트웨어를 사용자가 설치·사용할 수 있게 묶는 작업"},{"term":"패키징 고려 사항","desc":"사용자 중심, 사용자 실행 환경 고려, 직관적 UI, 관리 서비스 형태, 보안·DRM"}],"memo":"패키지는 받는 사람(고객)을 위해 포장한다. '개발자 중심'이면 틀린 보기다."}},{"id":"written-2022-1-30","no":30,"unit":"소프트웨어 개발","q":"자료 구조의 분류 중 선형 구조가 아닌 것은?","choices":["트리","리스트","스택","데크"],"ans":1,"rate":72,"wiki":[{"title":"자료 구조","url":"https://itwiki.kr/w/자료 구조"}],"exp":{"concept":"선형 구조는 데이터가 한 줄로 앞뒤 관계를 이루며 늘어선 구조로 배열, 리스트, 스택, 큐, 데크가 있다. 비선형 구조는 한 데이터가 여러 데이터와 연결되는 구조로 트리와 그래프가 있다. 트리는 나뭇가지처럼 한 부모 아래 여러 자식이 갈라지므로 선형이 아니다.","choices":[{"verdict":"정답","why":"트리(Tree)는 계층적으로 갈라지는 비선형 구조다. 선형 구조가 아니다."},{"verdict":"오답","why":"리스트(List)는 데이터가 순서대로 연결된 선형 구조다."},{"verdict":"오답","why":"스택(Stack)은 한쪽 끝에서만 넣고 빼는 선형 구조다."},{"verdict":"오답","why":"데크(Deque)는 양쪽 끝에서 넣고 뺄 수 있는 선형 구조다."}],"keywords":[{"term":"선형 구조","desc":"배열, 선형 리스트, 연결 리스트, 스택, 큐, 데크"},{"term":"비선형 구조","desc":"트리, 그래프"}],"memo":"비선형은 '트리·그래프' 두 개만 외우면 나머지는 모두 선형이다."}},{"id":"written-2022-1-31","no":31,"unit":"소프트웨어 개발","q":"아주 오래되거나 참고문서 또는 개발자가 없어 유지보수 작업이 아주 어려운 프로그램을 의미하는 것은?","choices":["Title Code","Source Code","Object Code","Alien Code"],"ans":4,"rate":95,"wiki":[{"title":"외계인 코드","url":"https://itwiki.kr/w/외계인 코드"}],"exp":{"concept":"에일리언 코드(Alien Code)는 너무 오래되었거나 참고할 문서나 개발자가 없어서 유지보수하기 매우 어려운 프로그램을 말한다. 외계인(Alien)이 쓴 것처럼 아무도 알아볼 수 없는 코드라고 생각하면 된다.","choices":[{"verdict":"오답","why":"Title Code는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"Source Code(원시 코드)는 사람이 프로그래밍 언어로 작성한, 번역 전의 프로그램이다."},{"verdict":"오답","why":"Object Code(목적 코드)는 원시 코드를 컴파일러가 기계어로 번역한 결과물이다."},{"verdict":"정답","why":"Alien Code는 아주 오래되었거나 참고 문서·개발자가 없어 유지보수가 매우 어려운 프로그램이다."}],"keywords":[{"term":"Alien Code","desc":"오래되고 문서·개발자가 없어 유지보수가 어려운 코드"},{"term":"Source Code","desc":"사람이 작성한 원시 프로그램"},{"term":"Object Code","desc":"컴파일 결과로 생긴 기계어 코드"}],"memo":"외계인이 남긴 코드라 아무도 해독 못 한다고 기억하자."}},{"id":"written-2022-1-32","no":32,"unit":"소프트웨어 개발","q":"소프트웨어를 재사용함으로써 얻을 수 있는 이점으로 가장 거리가 먼 것은?","choices":["생산성 증가","프로젝트 문서 공유","소프트웨어 품질 향상","새로운 개발 방법론 도입 용이"],"ans":4,"rate":74,"wiki":[{"title":"소프트웨어 재공학","url":"https://itwiki.kr/w/소프트웨어 재공학"}],"exp":{"concept":"소프트웨어 재사용은 이미 만들어 검증된 소프트웨어나 그 일부를 다른 개발에 다시 쓰는 것이다. 검증된 부품을 다시 쓰므로 생산성과 품질이 오르고 문서도 공유할 수 있다. 하지만 기존 것을 다시 쓰는 방식이라 새로운 개발 방법론을 도입하기는 오히려 어렵다.","choices":[{"verdict":"오답","why":"이미 만든 것을 다시 쓰므로 개발 시간이 줄어 생산성이 높아진다. 재사용의 이점이다."},{"verdict":"오답","why":"기존 프로젝트의 문서를 공유해 활용할 수 있다. 재사용의 이점이다."},{"verdict":"오답","why":"이미 검증된 소프트웨어를 쓰므로 품질이 좋아진다. 재사용의 이점이다."},{"verdict":"정답","why":"재사용은 기존 방식과 구성 요소를 그대로 쓰기 때문에 새로운 개발 방법론을 도입하기 어렵다는 단점이 있다. 이점과 거리가 멀다."}],"keywords":[{"term":"소프트웨어 재사용 이점","desc":"생산성 향상, 품질 향상, 개발 기간·비용 단축, 문서 공유, 프로젝트 실패 위험 감소"},{"term":"재사용 방법","desc":"합성 중심(블록 구성 방법), 생성 중심(패턴 구성 방법)"}],"memo":"옛것을 다시 쓰는데 '새 방법론 도입이 쉽다'는 말은 앞뒤가 안 맞는다."}},{"id":"written-2022-1-33","no":33,"unit":"소프트웨어 개발","q":"인터페이스 간의 통신을 위해 이용되는 데이터 포맷이 아닌 것은?","choices":["AJTML","JSON","XML","YAML"],"ans":1,"rate":61,"wiki":[{"title":"JSON","url":"https://itwiki.kr/w/JSON"},{"title":"XML","url":"https://itwiki.kr/w/XML"},{"title":"YAML","url":"https://itwiki.kr/w/YAML"}],"exp":{"concept":"시스템끼리 데이터를 주고받으려면 양쪽이 이해할 수 있는 형식(포맷)으로 데이터를 표현해야 한다. 인터페이스 통신에 주로 쓰이는 데이터 포맷은 JSON, XML, YAML 등이다. AJTML이라는 데이터 포맷은 존재하지 않는다.","choices":[{"verdict":"정답","why":"AJTML은 존재하지 않는 형식이다. 이름이 비슷한 AJAX(Asynchronous JavaScript and XML)는 데이터 포맷이 아니라 비동기로 서버와 통신하는 웹 기법이다."},{"verdict":"오답","why":"JSON(JavaScript Object Notation)은 속성-값 쌍으로 데이터를 표현하는 가벼운 텍스트 데이터 포맷이다."},{"verdict":"오답","why":"XML(eXtensible Markup Language)은 사용자가 태그를 정의해 데이터를 표현하는 마크업 언어로, 데이터 교환에 널리 쓰인다."},{"verdict":"오답","why":"YAML은 들여쓰기로 구조를 나타내는, 사람이 읽기 쉬운 데이터 직렬화 형식이다."}],"keywords":[{"term":"JSON","desc":"속성-값 쌍으로 표현하는 경량 데이터 교환 포맷"},{"term":"XML","desc":"태그로 구조를 정의하는 확장 가능한 마크업 언어"},{"term":"YAML","desc":"들여쓰기 기반의 읽기 쉬운 데이터 직렬화 형식"},{"term":"AJAX","desc":"페이지 전체를 새로 고치지 않고 비동기로 데이터를 주고받는 기법"}],"memo":"인터페이스 데이터 포맷은 JSON·XML·YAML(그리고 CSV 등). 처음 보는 이름은 의심하자."}},{"id":"written-2022-1-34","no":34,"unit":"소프트웨어 개발","q":"프로그램 설계도의 하나인 NS Chart에 대한 설명으로 가장 거리가 먼 것은?","choices":["논리의 기술에 중점을 두고 도형을 이용한 표현 방법이다.","이해하기 쉽고 코드 변환이 용이하다.","화살표나 GOTO를 사용하여 이해하기 쉽다.","연속, 선택, 반복 등의 제어 논리 구조를 표현한다."],"ans":3,"rate":59,"wiki":[{"title":"화살표 사용 안함","url":"https://itwiki.kr/w/화살표 사용 안함"}],"exp":{"concept":"NS 차트(Nassi-Schneiderman Chart)는 프로그램의 논리를 네모 상자로만 표현하는 구조적 설계도다. 순차, 선택, 반복의 세 가지 제어 구조만으로 그리며, 흐름을 마음대로 건너뛰는 화살표나 GOTO를 쓰지 않는 것이 특징이다.","choices":[{"verdict":"오답","why":"NS 차트는 논리의 기술에 중점을 두고 도형(상자)으로 표현하는 방법이다. 맞는 설명이다."},{"verdict":"오답","why":"구조가 단순해 이해하기 쉽고 코드로 옮기기도 쉽다. 맞는 설명이다."},{"verdict":"정답","why":"NS 차트는 화살표나 GOTO를 사용하지 않는다. 화살표·GOTO를 쓴다는 설명은 틀렸다."},{"verdict":"오답","why":"순차(연속), 선택, 반복 등의 제어 논리 구조를 표현한다. 맞는 설명이다."}],"keywords":[{"term":"NS 차트","desc":"상자 도형으로 순차·선택·반복을 표현하는 구조적 설계 도구, GOTO·화살표 없음"},{"term":"구조적 프로그래밍 3요소","desc":"순차(Sequence), 선택(Selection), 반복(Iteration)"}],"memo":"NS 차트는 상자 안에 상자를 넣는 그림이라 화살표가 들어갈 자리가 없다."}},{"id":"written-2022-1-35","no":35,"unit":"소프트웨어 개발","q":"순서가 A, B, C, D로 정해진 입력자료를 push, push, pop, push, push, pop, pop, pop 순서로 스택연산을 수행하는 경우 출력 결과는?","choices":["B D C A","A B C D","B A C D","A B D C"],"ans":1,"rate":78,"wiki":[{"title":"스택","url":"https://itwiki.kr/w/스택"}],"exp":{"concept":"스택은 나중에 넣은 것을 먼저 꺼내는(LIFO) 구조다. 입력 순서 A, B, C, D를 차례로 push하면서 pop이 나올 때마다 맨 위 값을 꺼내 출력하면 된다. push A → push B → pop(B 출력) → push C → push D → pop(D 출력) → pop(C 출력) → pop(A 출력) 순서로 진행된다.","choices":[{"verdict":"정답","why":"push A, push B 후 pop하면 B, push C, push D 후 pop하면 D, 이어서 pop하면 C, 마지막 pop하면 A가 나온다. 출력은 B D C A다."},{"verdict":"오답","why":"A B C D는 큐(FIFO)처럼 들어간 순서대로 나올 때의 결과다. 첫 pop 때 스택 맨 위에는 B가 있으므로 A가 먼저 나올 수 없다."},{"verdict":"오답","why":"B 다음 pop 시점에는 C, D가 이미 들어가 있어 맨 위가 D다. A가 두 번째로 나올 수 없다."},{"verdict":"오답","why":"첫 pop 때 스택은 [A, B]로 맨 위가 B이므로 A가 먼저 나올 수 없다."}],"keywords":[{"term":"스택(Stack)","desc":"LIFO 구조, 마지막에 넣은 것을 먼저 꺼냄"},{"term":"push / pop","desc":"push는 Top에 삽입, pop은 Top에서 삭제"},{"term":"큐(Queue)","desc":"FIFO 구조, 먼저 넣은 것을 먼저 꺼냄"}],"memo":"스택 문제는 종이에 칸을 그려 push·pop을 하나씩 따라가면 실수가 없다."}},{"id":"written-2022-1-36","no":36,"unit":"소프트웨어 개발","q":"분할 정복(Divide and Conquer)에 기반한 알고리즘으로 피벗(pivot)을 사용하며 최악의 경우 \n  회의 비교를 수행해야 하는 정렬(Sort)은?\n<img src=\"data/img/eip_written_20220305_036.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Selection Sort","Bubble Sort","Insert Sort","Quick Sort"],"ans":4,"rate":55,"wiki":[{"title":"정렬","url":"https://itwiki.kr/w/정렬"}],"exp":{"concept":"퀵 정렬(Quick Sort)은 기준값인 피벗(pivot)을 정해 피벗보다 작은 값과 큰 값으로 나누고, 나눈 부분을 다시 같은 방법으로 정렬하는 분할 정복(Divide and Conquer) 알고리즘이다. 평균 시간 복잡도는 O(n log n)이지만, 피벗이 매번 최솟값이나 최댓값으로 잡히는 최악의 경우 n(n-1)/2번 비교해 O(n²)이 된다.","choices":[{"verdict":"오답","why":"선택 정렬(Selection Sort)은 최솟값을 찾아 맨 앞과 교환하는 방식으로 n(n-1)/2번 비교하지만, 피벗을 쓰는 분할 정복 방식이 아니다."},{"verdict":"오답","why":"버블 정렬(Bubble Sort)은 이웃한 두 값을 비교해 교환하는 방식으로, 분할 정복이나 피벗을 쓰지 않는다."},{"verdict":"오답","why":"삽입 정렬(Insert Sort)은 정렬된 부분에 새 값을 알맞은 자리에 끼워 넣는 방식으로, 분할 정복이나 피벗을 쓰지 않는다."},{"verdict":"정답","why":"퀵 정렬(Quick Sort)은 피벗을 기준으로 분할 정복하며, 최악의 경우 n(n-1)/2번 비교한다."}],"keywords":[{"term":"퀵 정렬","desc":"피벗 기준 분할 정복, 평균 O(n log n), 최악 O(n²)"},{"term":"분할 정복","desc":"문제를 작게 나눠 각각 풀고 합치는 방법, 퀵 정렬·병합 정렬이 대표적"},{"term":"병합 정렬(Merge Sort)","desc":"분할 정복 방식이지만 피벗 없이 반으로 나눠 합침, 항상 O(n log n)"}],"memo":"'피벗'이 나오면 퀵 정렬. 분할 정복이지만 피벗이 없으면 병합 정렬이다."}},{"id":"written-2022-1-37","no":37,"unit":"소프트웨어 개발","q":"화이트 박스 검사 기법에 해당하는 것으로만 짝지어진 것은?\n<img src=\"data/img/eip_written_20220305_037.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠, ㉡","㉠, ㉣","㉡, ㉤","㉢, ㉥"],"ans":1,"rate":72,"wiki":[{"title":"화이트박스 테스트","url":"https://itwiki.kr/w/화이트박스 테스트"},{"title":"블랙박스 테스트","url":"https://itwiki.kr/w/블랙박스 테스트"}],"exp":{"concept":"화이트박스 검사는 프로그램 내부의 소스 코드와 논리 구조를 보면서 테스트하는 방법이고, 블랙박스 검사는 내부를 보지 않고 입력과 출력만으로 기능을 테스트하는 방법이다. 데이터 흐름 검사와 루프 검사는 코드 내부의 변수 흐름과 반복문을 따라가므로 화이트박스 검사다.","choices":[{"verdict":"정답","why":"㉠ 데이터 흐름 검사는 변수의 정의와 사용 위치를 따라가는 검사, ㉡ 루프 검사는 반복 구조를 중점적으로 검사하는 것으로 둘 다 화이트박스 검사다."},{"verdict":"오답","why":"㉣ 경계값 분석은 입력 범위의 경계 근처 값으로 테스트하는 블랙박스 검사다."},{"verdict":"오답","why":"㉤ 원인-결과 그래프 기법은 입력(원인)과 출력(결과)의 관계를 그래프로 분석하는 블랙박스 검사다."},{"verdict":"오답","why":"㉢ 동등 분할 검사와 ㉥ 오류 예측 기법은 모두 블랙박스 검사다."}],"keywords":[{"term":"화이트박스 검사","desc":"기초 경로 검사, 제어 구조 검사(조건 검사, 루프 검사, 데이터 흐름 검사)"},{"term":"블랙박스 검사","desc":"동치(동등) 분할, 경계값 분석, 원인-결과 그래프, 오류 예측, 비교 검사"}],"memo":"블랙박스는 '동경원오비'(동치 분할, 경계값, 원인-결과, 오류 예측, 비교). 나머지 코드 내부를 보는 것은 화이트박스."}},{"id":"written-2022-1-38","no":38,"unit":"소프트웨어 개발","q":"소프트웨어 품질 관련 국제 표준인 ISO/IEC 25000에 관한 설명으로 옳지 않은 것은?","choices":["소프트웨어 품질 평가를 위한 소프트웨어 품질평가 통합모델 표준이다.","System and Software Quality Requirements and Evaluation으로 줄여서 SQuaRE라고도 한다.","ISO/IEC 2501n에서는 소프트웨어의 내부 측정, 외부측정, 사용품질 측정, 품질 측정 요소 등을 다룬다.","기존 소프트웨어 품질 평가 모델과 소프트웨어 평가 절차 모델인 ISO/IEC 9126과 ISO/IEC 14598을 통합하였다."],"ans":3,"rate":59,"wiki":[{"title":"SQuaRE","url":"https://itwiki.kr/w/SQuaRE"}],"exp":{"concept":"ISO/IEC 25000(SQuaRE)은 소프트웨어 품질 평가를 위한 통합 국제 표준으로, 기존의 ISO/IEC 9126(품질 특성)과 ISO/IEC 14598(평가 절차)을 하나로 합친 것이다. 다섯 개 분야로 나뉘는데 2501n은 품질 모델을, 2502n은 품질 측정을 다룬다.","choices":[{"verdict":"오답","why":"ISO/IEC 25000은 소프트웨어 품질 평가를 위한 통합 모델 표준이다. 맞는 설명이다."},{"verdict":"오답","why":"System and Software Quality Requirements and Evaluation의 약자로 SQuaRE라고 부른다. 맞는 설명이다."},{"verdict":"정답","why":"내부 측정, 외부 측정, 사용 품질 측정, 품질 측정 요소 등을 다루는 것은 ISO/IEC 2502n(품질 측정)이다. 2501n은 품질 모델을 다루므로 틀린 설명이다."},{"verdict":"오답","why":"기존의 ISO/IEC 9126과 ISO/IEC 14598을 통합한 표준이다. 맞는 설명이다."}],"keywords":[{"term":"ISO/IEC 25000 (SQuaRE)","desc":"9126 + 14598을 통합한 소프트웨어 품질 평가 표준"},{"term":"SQuaRE 분야","desc":"2500n 품질 관리, 2501n 품질 모델, 2502n 품질 측정, 2503n 품질 요구, 2504n 품질 평가"},{"term":"ISO/IEC 9126","desc":"소프트웨어 품질 특성 표준(기능성, 신뢰성, 사용성, 효율성, 유지보수성, 이식성)"}],"memo":"2500n~2504n은 '관리-모델-측정-요구-평가' 순서. 측정은 2502n이다."}},{"id":"written-2022-1-39","no":39,"unit":"소프트웨어 개발","q":"코드 인스펙션과 관련한 설명으로 틀린 것은?","choices":["프로그램을 수행시켜보는 것 대신에 읽어보고 눈으로 확인하는 방법으로 볼 수 있다.","코드 품질 향상 기법 중 하나이다.","동적 테스트 시에만 활용하는 기법이다.","결함과 함께 코딩 표준 준수 여부, 효율성 등의 다른 품질 이슈를 검사하기도 한다."],"ans":3,"rate":77,"wiki":[{"title":"코드 인스펙션","url":"https://itwiki.kr/w/코드 인스펙션"},{"title":"정적 테스트","url":"https://itwiki.kr/w/정적 테스트"}],"exp":{"concept":"코드 인스펙션(Code Inspection)은 프로그램을 실행하지 않고 사람이 코드를 직접 읽어 보며 결함을 찾는 정적 테스트 기법이다. 결함뿐 아니라 코딩 표준 준수, 효율성 같은 품질 문제도 함께 검사한다. 프로그램을 실행해 보는 동적 테스트와는 반대다.","choices":[{"verdict":"오답","why":"코드 인스펙션은 프로그램을 수행하지 않고 읽고 눈으로 확인하는 방법이다. 맞는 설명이다."},{"verdict":"오답","why":"코드 인스펙션은 코드의 품질을 높이는 기법 중 하나다. 맞는 설명이다."},{"verdict":"정답","why":"코드 인스펙션은 프로그램을 실행하지 않는 정적 테스트 기법이다. 동적 테스트 시에만 활용한다는 설명은 틀렸다."},{"verdict":"오답","why":"결함과 함께 코딩 표준 준수 여부, 효율성 등 다른 품질 이슈도 검사한다. 맞는 설명이다."}],"keywords":[{"term":"정적 테스트","desc":"프로그램을 실행하지 않고 검토, 워크스루, 인스펙션, 정적 분석 도구"},{"term":"동적 테스트","desc":"프로그램을 실행하며 화이트박스·블랙박스 테스트"},{"term":"코드 인스펙션","desc":"코드를 읽어 결함을 찾는 공식적인 정적 검토 기법"}],"memo":"인스펙션(Inspection)은 '검사·점검'이다. 실행하지 않고 눈으로 보는 정적 기법."}},{"id":"written-2022-1-40","no":40,"unit":"소프트웨어 개발","q":"프로젝트에 내재된 위험 요소를 인식하고 그 영향을 분석하여 이를 관리하는 활동으로서, 프로젝트를 성공시키기 위하여 위험 요소를 사전에 예측, 대비하는 모든 기술과 활동을 포함하는 것은?","choices":["Critical Path Method","Risk Analysis","Work Breakdown Structure","Waterfall Model"],"ans":2,"rate":83,"wiki":[{"title":"위험","url":"https://itwiki.kr/w/위험"},{"title":"CPM","url":"https://itwiki.kr/w/CPM"},{"title":"WBS","url":"https://itwiki.kr/w/WBS"}],"exp":{"concept":"위험 분석(Risk Analysis)은 프로젝트에 숨어 있는 위험 요소를 미리 찾아내고 그 영향을 분석해 관리하는 활동이다. 프로젝트를 성공시키기 위해 문제가 생기기 전에 예측하고 대비한다. 여행 전에 날씨와 사고 가능성을 미리 따져 우산과 보험을 챙기는 것과 같다.","choices":[{"verdict":"오답","why":"CPM(Critical Path Method, 임계 경로 기법)은 작업 순서와 소요 기간을 네트워크로 그려 프로젝트 완료에 걸리는 가장 긴 경로를 찾는 일정 관리 기법이다."},{"verdict":"정답","why":"Risk Analysis(위험 분석)는 위험 요소를 인식하고 영향을 분석해 사전에 예측·대비하는 관리 활동이다."},{"verdict":"오답","why":"WBS(Work Breakdown Structure, 작업 분해 구조)는 프로젝트 작업을 계층적으로 잘게 나눈 구조로, 일정·비용 계획의 기초가 된다."},{"verdict":"오답","why":"Waterfall Model(폭포수 모델)은 각 단계를 순서대로 한 번씩 진행하는 소프트웨어 생명주기 모델이다."}],"keywords":[{"term":"위험 관리 절차","desc":"위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치"},{"term":"CPM","desc":"임계 경로로 프로젝트 최소 완료 기간을 구하는 일정 관리 기법"},{"term":"WBS","desc":"프로젝트 작업을 계층적으로 분해한 구조"}],"memo":"위험(Risk)을 미리 예측·대비하면 Risk Analysis. 일정이면 CPM·PERT·간트 차트."}},{"id":"written-2022-1-41","no":41,"unit":"데이터베이스 구축","q":"데이터베이스 설계 단계 중 물리적 설계 시 고려 사항으로 적절하지 않은 것은?","choices":["스키마의 평가 및 정제","응답 시간","저장 공간의 효율화","트랜잭션 처리량"],"ans":1,"rate":66,"exp":{"concept":"데이터베이스 설계는 요구 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행한다. 물리적 설계는 실제 저장 장치에 어떻게 저장하고 접근할지를 정하는 단계라서 응답 시간, 저장 공간 효율, 트랜잭션 처리량 같은 성능 요소를 고려한다. 스키마를 평가하고 정제하는 일은 그 전 단계인 논리적 설계에서 한다.","choices":[{"verdict":"정답","why":"스키마의 평가 및 정제는 논리적 설계 단계에서 하는 일이다. 물리적 설계의 고려 사항이 아니다."},{"verdict":"오답","why":"응답 시간은 사용자 요청에 데이터베이스가 얼마나 빨리 답하는지로, 물리적 설계에서 고려하는 성능 요소다."},{"verdict":"오답","why":"저장 공간의 효율화는 데이터를 실제 저장 장치에 얼마나 효율적으로 담을지로, 물리적 설계의 고려 사항이다."},{"verdict":"오답","why":"트랜잭션 처리량은 단위 시간당 처리할 수 있는 트랜잭션 수로, 물리적 설계의 고려 사항이다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS에 독립적인 개념 스키마"},{"term":"논리적 설계","desc":"특정 DBMS 모델(관계형 등)로 변환, 정규화, 스키마 평가 및 정제"},{"term":"물리적 설계","desc":"저장 레코드 양식, 인덱스·접근 경로 설계, 응답 시간·저장 공간·트랜잭션 처리량 고려"}],"memo":"물리적 설계는 '성능 숫자'(시간·공간·처리량), 논리적 설계는 '스키마 다듬기'."}},{"id":"written-2022-1-42","no":42,"unit":"데이터베이스 구축","q":"DELETE 명령에 대한 설명으로 틀린 것은?","choices":["테이블의 행을 삭제할 때 사용한다.","WHERE 조건절이 없는 DELETE 명령을 수행하면 DROP TABLE 명령을 수행했을 때와 동일한 효과를 얻을 수 있다.","SQL을 사용 용도에 따라 분류할 경우 DML에 해당한다.","기본 사용 형식은 “DELETE FROM 테이블 [WHERE 조건];” 이다."],"ans":2,"rate":74,"exp":{"concept":"DELETE는 테이블의 행(튜플)을 삭제하는 DML(데이터 조작어) 명령이다. WHERE 없이 실행하면 모든 행이 지워지지만 테이블 자체(구조)는 그대로 남아 빈 테이블이 된다. DROP TABLE은 테이블 구조까지 통째로 없애므로 결과가 다르다.","choices":[{"verdict":"오답","why":"DELETE는 테이블의 행을 삭제할 때 사용한다. 맞는 설명이다."},{"verdict":"정답","why":"WHERE 없는 DELETE는 모든 행을 지우지만 테이블 구조는 남는다. DROP TABLE은 테이블 자체를 제거하므로 같은 효과가 아니다. 틀린 설명이다."},{"verdict":"오답","why":"DELETE는 SELECT, INSERT, UPDATE와 함께 데이터 조작어(DML)에 속한다. 맞는 설명이다."},{"verdict":"오답","why":"기본 형식은 DELETE FROM 테이블 [WHERE 조건]; 이다. 맞는 설명이다."}],"keywords":[{"term":"DELETE","desc":"DML, 행 삭제, 테이블 구조는 남음"},{"term":"DROP TABLE","desc":"DDL, 테이블 구조와 데이터를 모두 제거"},{"term":"TRUNCATE","desc":"DDL, 테이블 구조는 남기고 모든 행을 한 번에 삭제"}],"memo":"DELETE는 내용물만 비우고 상자는 남기고, DROP은 상자째 버린다."}},{"id":"written-2022-1-43","no":43,"unit":"데이터베이스 구축","q":"어떤 릴레이션 R의 모든 조인 종속성의 만족이 R의 후보 키를 통해서만 만족될 때, 이 릴레이션 R이 해당하는 정규형은?","choices":["제5정규형","제4정규형","제3정규형","제1정규형"],"ans":1,"rate":60,"exp":{"concept":"정규화는 이상 현상을 없애기 위해 릴레이션을 단계적으로 쪼개는 과정이다. 제5정규형(5NF)은 릴레이션의 모든 조인 종속성(Join Dependency)이 후보 키를 통해서만 성립하는 상태다. 즉, 후보 키와 상관없는 조인 종속을 제거해야 도달한다.","choices":[{"verdict":"정답","why":"제5정규형은 모든 조인 종속성이 후보 키를 통해서만 만족되는 정규형이다."},{"verdict":"오답","why":"제4정규형은 다치 종속(MVD, Multi-Valued Dependency)을 제거한 정규형이다."},{"verdict":"오답","why":"제3정규형은 이행적 함수 종속을 제거한 정규형이다."},{"verdict":"오답","why":"제1정규형은 모든 속성의 도메인이 원자값으로만 이루어진 정규형이다."}],"keywords":[{"term":"1NF","desc":"도메인이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거"},{"term":"3NF","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자가 모두 후보 키"},{"term":"4NF / 5NF","desc":"다치 종속 제거 / 후보 키를 통하지 않는 조인 종속 제거"}],"memo":"'도부이결다조'(원자값-부분-이행-결정자-다치-조인). '조인 종속'이면 5NF."}},{"id":"written-2022-1-44","no":44,"unit":"데이터베이스 구축","q":"E-R 모델에서 다중값 속성의 표기법은?","choices":["<img src=\"data/img/eip_written_20220305_044_c1.png\" alt=\"마름모 도형\" />","<img src=\"data/img/eip_written_20220305_044_c2.png\" alt=\"사각형 도형\" />","<img src=\"data/img/eip_written_20220305_044_c3.png\" alt=\"이중 타원 도형\" />","<img src=\"data/img/eip_written_20220305_044_c4.png\" alt=\"굵은 실선\" />"],"ans":3,"rate":87,"exp":{"concept":"E-R 다이어그램에서는 기호 모양으로 의미를 구분한다. 개체는 사각형, 관계는 마름모, 속성은 타원, 연결은 선으로 그린다. 속성 중 값을 여러 개 가질 수 있는 다중값 속성(예: 전화번호, 취미)은 타원을 두 겹으로 그린 이중 타원으로 표시한다.","choices":[{"verdict":"오답","why":"마름모는 개체 사이의 관계(Relationship)를 나타내는 기호다."},{"verdict":"오답","why":"사각형은 개체(Entity)를 나타내는 기호다."},{"verdict":"정답","why":"이중 타원은 값을 여러 개 가질 수 있는 다중값 속성(Multivalued Attribute)을 나타낸다."},{"verdict":"오답","why":"선(실선)은 개체와 속성, 개체와 관계를 연결하는 기호다."}],"keywords":[{"term":"E-R 기본 기호","desc":"사각형 개체, 마름모 관계, 타원 속성, 선 연결"},{"term":"이중 타원","desc":"다중값 속성"},{"term":"밑줄 친 타원","desc":"기본 키 속성"},{"term":"점선 타원","desc":"유도(파생) 속성"},{"term":"이중 사각형","desc":"약한 개체"}],"memo":"'두 겹'은 여럿이나 약함을 뜻한다: 이중 타원은 다중값 속성, 이중 사각형은 약한 개체."}},{"id":"written-2022-1-45","no":45,"unit":"데이터베이스 구축","q":"다른 릴레이션의 기본키를 참조하는 키를 의미하는 것은?","choices":["필드키","슈퍼키","외래키","후보키"],"ans":3,"rate":80,"exp":{"concept":"외래키(Foreign Key)는 한 릴레이션의 속성이 다른 릴레이션의 기본키를 참조하는 키다. 두 테이블을 이어 주는 연결 고리 역할을 하며, 참조 무결성 제약 조건으로 참조하는 값이 실제로 존재하도록 보장한다.","choices":[{"verdict":"오답","why":"필드키는 출제 범위의 표준 키 종류가 아니다."},{"verdict":"오답","why":"슈퍼키(Super Key)는 튜플을 유일하게 구분할 수 있는 속성 또는 속성들의 집합으로, 유일성만 만족하면 된다."},{"verdict":"정답","why":"외래키(Foreign Key)는 다른 릴레이션의 기본키를 참조하는 속성(집합)이다."},{"verdict":"오답","why":"후보키(Candidate Key)는 튜플을 유일하게 식별하는 속성 집합 중 유일성과 최소성을 모두 만족하는 키다."}],"keywords":[{"term":"후보키","desc":"유일성 + 최소성"},{"term":"슈퍼키","desc":"유일성만 만족"},{"term":"기본키","desc":"후보키 중 선택한 대표 키, NULL·중복 불가"},{"term":"대체키","desc":"후보키 중 기본키가 아닌 나머지"},{"term":"외래키","desc":"다른 릴레이션의 기본키를 참조"}],"memo":"Foreign은 '외부의'다. 외부(다른) 테이블의 기본키를 가리키면 외래키."}},{"id":"written-2022-1-46","no":46,"unit":"데이터베이스 구축","q":"관계해석에서 '모든 것에 대하여'의 의미를 나타내는 논리 기호는?","choices":["∃","∈","∀","⊂"],"ans":3,"rate":72,"wiki":[{"title":"관계해석","url":"https://itwiki.kr/w/관계해석"}],"exp":{"concept":"관계 해석은 원하는 데이터가 '무엇인지'를 술어 논리 기호로 적는 비절차적 질의 방법이다. '모든 것에 대하여'를 뜻하는 전칭 정량자는 ∀(For All)이고, '어떤 것이 존재한다'를 뜻하는 존재 정량자는 ∃(There Exists)이다.","choices":[{"verdict":"오답","why":"∃는 존재 정량자로 '어떤 것이 존재한다(There Exists)'는 뜻이다."},{"verdict":"오답","why":"∈는 '어떤 집합의 원소이다'를 나타내는 기호다."},{"verdict":"정답","why":"∀는 전칭 정량자로 '모든 것에 대하여(For All)'를 뜻한다."},{"verdict":"오답","why":"⊂는 '부분집합이다'를 나타내는 기호다."}],"keywords":[{"term":"∀ (전칭 정량자)","desc":"모든 것에 대하여, For All"},{"term":"∃ (존재 정량자)","desc":"어떤 것이 존재한다, There Exists"},{"term":"관계 해석","desc":"원하는 정보가 무엇인지만 정의하는 비절차적 언어"},{"term":"관계 대수","desc":"원하는 정보를 얻는 절차를 기술하는 절차적 언어"}],"memo":"∀는 All의 A를 뒤집은 모양, ∃는 Exists의 E를 뒤집은 모양이다."}},{"id":"written-2022-1-47","no":47,"unit":"데이터베이스 구축","q":"다음 릴레이션의 Degree와 Cardinality는?\n<img src=\"data/img/eip_written_20220305_047.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Degree : 4, Cardinality : 3","Degree : 3, Cardinality : 4","Degree : 3, Cardinality : 12","Degree : 12, Cardinality : 3"],"ans":1,"rate":72,"wiki":[{"title":"릴레이션","url":"https://itwiki.kr/w/릴레이션"}],"exp":{"concept":"릴레이션(테이블)에서 디그리(Degree)는 속성(열)의 개수, 카디널리티(Cardinality)는 튜플(행)의 개수다. 제시된 테이블은 학번, 이름, 학년, 학과의 4개 열과 13001, 13002, 13003의 3개 행으로 되어 있다.","choices":[{"verdict":"정답","why":"열이 학번·이름·학년·학과 4개이므로 Degree는 4, 행이 3개이므로 Cardinality는 3이다."},{"verdict":"오답","why":"Degree와 Cardinality를 서로 바꿔 놓은 값이다."},{"verdict":"오답","why":"Cardinality 12는 4 × 3으로 칸(셀) 개수이며, Degree도 3이 아니다."},{"verdict":"오답","why":"Degree 12는 셀 개수로, 디그리는 속성 개수 4다."}],"keywords":[{"term":"디그리(Degree, 차수)","desc":"속성(열)의 개수"},{"term":"카디널리티(Cardinality, 기수)","desc":"튜플(행)의 개수"},{"term":"튜플(Tuple)","desc":"릴레이션의 한 행"},{"term":"도메인(Domain)","desc":"한 속성이 가질 수 있는 값의 범위"}],"memo":"디그리는 '세로 줄(열) 수', 카디널리티는 '가로 줄(행) 수'. 헤더 행은 카디널리티에 넣지 않는다."}},{"id":"written-2022-1-48","no":48,"unit":"데이터베이스 구축","q":"뷰(View)에 대한 설명으로 틀린 것은?","choices":["뷰 위에 또 다른 뷰를 정의할 수 있다.","DBA는 보안성 측면에서 뷰를 활용할 수 있다.","사용자가 필요한 정보를 요구에 맞게 가공하여 뷰로 만들 수 있다.","SQL을 사용하면 뷰에 대한 삽입, 갱신, 삭제 연산 시 제약 사항이 없다."],"ans":4,"rate":85,"exp":{"concept":"뷰(View)는 하나 이상의 기본 테이블에서 필요한 데이터만 뽑아 만든 가상 테이블이다. 뷰 위에 다른 뷰를 만들 수 있고, 보여 주고 싶은 열만 공개해 보안에 활용할 수 있다. 다만 실제 데이터가 아니라 가상이므로 삽입·수정·삭제에는 제약이 따른다.","choices":[{"verdict":"오답","why":"뷰를 바탕으로 또 다른 뷰를 정의할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"필요한 데이터만 보여 줄 수 있어 DBA가 보안 수단으로 활용할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"사용자 요구에 맞게 데이터를 가공해 뷰로 만들 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"뷰는 가상 테이블이라 조인이나 집계로 만든 뷰 등은 삽입·갱신·삭제가 제한된다. 제약 사항이 없다는 설명은 틀렸다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 독립성 제공, 데이터 보안, 사용자 데이터 관리 단순화"},{"term":"뷰의 단점","desc":"독립적인 인덱스를 가질 수 없음, 정의 변경 불가(ALTER 불가), 삽입·갱신·삭제에 제약"}],"memo":"뷰는 '가상'이다. 가상에 데이터를 넣고 고치는 것은 제약이 있다고 기억하자."}},{"id":"written-2022-1-49","no":49,"unit":"데이터베이스 구축","q":"관계 대수식을 SQL 질의로 옳게 표현한 것은?\n<img src=\"data/img/eip_written_20220305_049.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SELECT 학생 FROM 이름 WHERE 학과='교육';","SELECT 이름 FROM 학생 WHERE 학과='교육';","SELECT 교육 FROM 학과 WHERE 이름='학생';","SELECT 학과 FROM 학생 WHERE 이름='교육';"],"ans":2,"rate":75,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계 대수식은 안쪽 괄호부터 읽는다. 식 π이름(σ학과='교육'(학생))은 학생 릴레이션에서(FROM) 학과가 '교육'인 행을 고르고(σ → WHERE), 그중 이름 열만 뽑는다(π → SELECT)는 뜻이다.","choices":[{"verdict":"오답","why":"'이름' 테이블에서 '학생' 열을 뽑는다는 뜻이 되어 테이블과 속성의 자리가 뒤바뀌었다."},{"verdict":"정답","why":"π이름은 SELECT 이름, 대상 릴레이션 학생은 FROM 학생, σ학과='교육'은 WHERE 학과='교육'으로 옮겨진다. 올바른 표현이다."},{"verdict":"오답","why":"'학과' 테이블에서 '교육' 열을 뽑고 이름이 '학생'인 행을 찾는 식으로, 식과 전혀 맞지 않는다."},{"verdict":"오답","why":"SELECT 대상이 이름이 아니라 학과이고, 조건도 이름='교육'으로 바뀌어 있다."}],"keywords":[{"term":"σ (Select, 셀렉트)","desc":"조건에 맞는 행(튜플)을 고름, SQL의 WHERE"},{"term":"π (Project, 프로젝트)","desc":"지정한 열(속성)만 뽑음, SQL의 SELECT 열 목록"},{"term":"⋈ (Join)","desc":"공통 속성으로 두 릴레이션을 합침"}],"memo":"σ는 행을 가로로 거르고, π는 열을 세로로 자른다. 안쪽 괄호부터 읽자."}},{"id":"written-2022-1-50","no":50,"unit":"데이터베이스 구축","q":"정규화 과정에서 함수 종속이 A→B 이고 B→C 일 때 A→C인 관계를 제거하는 단계는?","choices":["1NF → 2NF","2NF → 3NF","3NF → BCNF","BCNF → 4NF"],"ans":2,"rate":63,"exp":{"concept":"함수 종속 A→B, B→C가 있으면 A→C가 저절로 성립하는데, 이것을 이행적 함수 종속이라고 한다. 이행적 함수 종속을 없애는 단계는 제2정규형에서 제3정규형으로 가는 과정이다. 친구의 친구를 거쳐 연결되는 간접 관계를 끊어 낸다고 생각하면 된다.","choices":[{"verdict":"오답","why":"1NF → 2NF에서는 기본키의 일부에만 종속되는 부분 함수 종속을 제거한다."},{"verdict":"정답","why":"2NF → 3NF에서는 A→B, B→C에서 생기는 A→C 같은 이행적 함수 종속을 제거한다."},{"verdict":"오답","why":"3NF → BCNF에서는 결정자이면서 후보 키가 아닌 것을 제거한다."},{"verdict":"오답","why":"BCNF → 4NF에서는 다치 종속을 제거한다."}],"keywords":[{"term":"이행적 함수 종속","desc":"A→B, B→C일 때 A→C가 성립하는 종속, 3NF에서 제거"},{"term":"부분 함수 종속","desc":"기본키 일부에만 종속, 2NF에서 제거"},{"term":"BCNF","desc":"모든 결정자가 후보 키"}],"memo":"'이행'은 3NF, '부분'은 2NF. 'A→B→C'가 보이면 바로 3NF."}},{"id":"written-2022-1-51","no":51,"unit":"데이터베이스 구축","q":"CREATE TABLE문에 포함되지 않는 기능은?","choices":["속성 타입 변경","속성의 NOT NULL 여부 지정","기본키를 구성하는 속성 지정","CHECK 제약조건의 정의"],"ans":1,"rate":63,"exp":{"concept":"CREATE TABLE은 새 테이블을 만드는 DDL(데이터 정의어) 명령이다. 테이블을 만들면서 속성 이름과 타입, NOT NULL, 기본키(PRIMARY KEY), 외래키(FOREIGN KEY), CHECK 같은 제약 조건을 함께 정의한다. 이미 만들어진 테이블의 속성 타입을 바꾸는 것은 ALTER TABLE이 하는 일이다.","choices":[{"verdict":"정답","why":"이미 정의된 속성의 타입을 변경하는 것은 ALTER TABLE 명령의 기능이다. CREATE TABLE에 포함되지 않는다."},{"verdict":"오답","why":"CREATE TABLE에서 속성마다 NOT NULL을 지정해 빈 값을 허용하지 않게 할 수 있다."},{"verdict":"오답","why":"CREATE TABLE에서 PRIMARY KEY로 기본키를 구성하는 속성을 지정할 수 있다."},{"verdict":"오답","why":"CREATE TABLE에서 CHECK로 속성 값에 대한 조건(제약)을 정의할 수 있다."}],"keywords":[{"term":"CREATE TABLE","desc":"테이블 생성, 속성·타입·NOT NULL·PRIMARY KEY·FOREIGN KEY·CHECK 정의"},{"term":"ALTER TABLE","desc":"기존 테이블에 속성 추가(ADD)·변경(ALTER/MODIFY)·삭제(DROP)"},{"term":"DDL","desc":"CREATE, ALTER, DROP"}],"memo":"'변경'이라는 말이 나오면 CREATE가 아니라 ALTER다."}},{"id":"written-2022-1-52","no":52,"unit":"데이터베이스 구축","q":"SQL과 관련한 설명으로 틀린 것은?","choices":["REVOKE 키워드를 사용하여 열 이름을 다시 부여할 수 있다.","데이터 정의어는 기본 테이블, 뷰 테이블, 또는 인덱스 등을 생성, 변경, 제거하는데 사용되는 명령어이다.","DISTINCT를 활용하여 중복 값을 제거할 수 있다.","JOIN을 통해 여러 테이블의 레코드를 조합하여 표현할 수 있다."],"ans":1,"rate":75,"exp":{"concept":"SQL 명령은 DDL(정의: CREATE, ALTER, DROP), DML(조작: SELECT, INSERT, UPDATE, DELETE), DCL(제어: GRANT, REVOKE, COMMIT, ROLLBACK)로 나뉜다. REVOKE는 사용자에게 주었던 권한을 회수하는 DCL 명령이며, 열 이름을 바꾸는 기능은 없다.","choices":[{"verdict":"정답","why":"REVOKE는 사용자에게 부여했던 권한을 취소(회수)하는 명령이다. 열 이름을 다시 부여하는 기능이 아니므로 틀린 설명이다."},{"verdict":"오답","why":"데이터 정의어(DDL)는 테이블, 뷰, 인덱스 등을 생성(CREATE)·변경(ALTER)·제거(DROP)하는 명령어다. 맞는 설명이다."},{"verdict":"오답","why":"SELECT DISTINCT를 쓰면 검색 결과에서 중복된 행을 한 번만 표시한다. 맞는 설명이다."},{"verdict":"오답","why":"JOIN은 두 개 이상의 테이블을 공통 속성으로 연결해 레코드를 조합한다. 맞는 설명이다."}],"keywords":[{"term":"GRANT / REVOKE","desc":"권한 부여 / 권한 회수(DCL)"},{"term":"DISTINCT","desc":"검색 결과의 중복 행 제거"},{"term":"AS","desc":"검색 결과의 열에 별칭을 붙임"}],"memo":"REVOKE는 '취소하다'라는 뜻이다. 권한을 거둬들이는 명령으로만 기억하자."}},{"id":"written-2022-1-53","no":53,"unit":"데이터베이스 구축","q":"다음 SQL문의 실행결과로 생성되는 튜플 수는?\n<img src=\"data/img/eip_written_20220305_053.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["1","3","4","5"],"ans":4,"rate":82,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"SELECT 문은 조건(WHERE)이 없으면 테이블의 모든 행을 결과로 돌려준다. 같은 값이 여러 번 나와도 DISTINCT를 쓰지 않으면 중복을 지우지 않는다. 사원 테이블의 행이 5개이므로 SELECT 급여 FROM 사원; 의 결과도 5개 튜플이다.","choices":[{"verdict":"오답","why":"1개가 되려면 COUNT(*)처럼 집계 함수를 쓰거나 한 행만 고르는 조건이 있어야 한다."},{"verdict":"오답","why":"3개는 SELECT DISTINCT 급여로 중복을 제거했을 때(30000, 35000, 40000)의 개수다. 문제의 SQL에는 DISTINCT가 없다."},{"verdict":"오답","why":"4개가 될 근거가 없다. WHERE 조건이 없으므로 모든 행이 나온다."},{"verdict":"정답","why":"WHERE 조건과 DISTINCT가 없으므로 5개 행의 급여 30000, 35000, 40000, 35000, 40000이 모두 출력되어 튜플 수는 5다."}],"keywords":[{"term":"DISTINCT","desc":"SELECT 결과의 중복 행을 제거"},{"term":"ALL","desc":"중복을 포함해 모두 출력, 생략 시 기본값"},{"term":"튜플","desc":"릴레이션의 행 하나"}],"memo":"SELECT는 기본이 ALL이다. DISTINCT가 없으면 중복 값도 그대로 센다."}},{"id":"written-2022-1-54","no":54,"unit":"데이터베이스 구축","q":"다음 SQL문에서 사용된 BETWEEN 연산의 의미와 동일한 것은?\n<img src=\"data/img/eip_written_20220305_054.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["점수 ＞= 90 AND 점수 ＜= 95","점수 ＞ 90 AND 점수 ＜ 95","점수 ＞ 90 AND 점수 ＜= 95","점수 ＞= 90 AND 점수 ＜ 95"],"ans":1,"rate":81,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"BETWEEN A AND B는 값이 A 이상 B 이하인지 검사하는 연산자로, 양쪽 끝값을 모두 포함한다. 따라서 점수 BETWEEN 90 AND 95는 점수 >= 90 AND 점수 <= 95와 같다.","choices":[{"verdict":"정답","why":"BETWEEN은 양 끝값을 포함하므로 점수 >= 90 AND 점수 <= 95와 같다."},{"verdict":"오답","why":"90과 95를 모두 제외한 범위로, BETWEEN과 다르다. 점수가 90이나 95인 행이 빠진다."},{"verdict":"오답","why":"아래 끝값 90을 제외했으므로 BETWEEN과 다르다."},{"verdict":"오답","why":"위 끝값 95를 제외했으므로 BETWEEN과 다르다."}],"keywords":[{"term":"BETWEEN A AND B","desc":"A 이상 B 이하, 양 끝값 포함"},{"term":"IN","desc":"나열한 값 중 하나와 같은지 검사"},{"term":"LIKE","desc":"%, _ 와일드카드로 문자열 패턴 검사"}],"memo":"BETWEEN은 '사이'지만 경계도 포함한다. >= 와 <= 로 바꾸면 된다."}},{"id":"written-2022-1-55","no":55,"unit":"데이터베이스 구축","q":"트랜잭션의 상태 중 트랜잭션의 수행이 실패하여 Rollback 연산을 실행한 상태는?","choices":["철회(Aborted)","부분 완료(Partially Committed)","완료(Commit)","실패(Fail)"],"ans":1,"rate":76,"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"exp":{"concept":"트랜잭션은 실행되는 동안 여러 상태를 거친다. 실행 중이면 활동(Active), 마지막 연산까지 실행했지만 아직 COMMIT 전이면 부분 완료(Partially Committed), 성공적으로 끝나 COMMIT하면 완료(Committed), 오류로 중단되면 실패(Failed), 실패한 트랜잭션을 ROLLBACK해 원래대로 되돌리면 철회(Aborted) 상태가 된다.","choices":[{"verdict":"정답","why":"철회(Aborted)는 트랜잭션 실행이 실패해 Rollback 연산을 수행한 상태다."},{"verdict":"오답","why":"부분 완료(Partially Committed)는 마지막 연산까지 실행을 마쳤지만 아직 Commit 연산을 실행하기 직전의 상태다."},{"verdict":"오답","why":"완료(Committed)는 트랜잭션이 성공적으로 끝나 Commit 연산을 실행한 상태다."},{"verdict":"오답","why":"실패(Failed)는 실행 중 오류가 발생해 중단된 상태로, Rollback을 하기 전의 상태다."}],"keywords":[{"term":"트랜잭션 상태","desc":"활동(Active), 부분 완료(Partially Committed), 완료(Committed), 실패(Failed), 철회(Aborted)"},{"term":"Commit","desc":"트랜잭션 결과를 데이터베이스에 영구 반영"},{"term":"Rollback","desc":"트랜잭션이 한 작업을 취소하고 이전 상태로 되돌림"}],"memo":"실패(Failed)는 '멈춘' 상태, 철회(Aborted)는 '되돌린(Rollback)' 상태로 구분하자."}},{"id":"written-2022-1-56","no":56,"unit":"데이터베이스 구축","q":"데이터 제어어(DCL)에 대한 설명으로 옳은 것은?","choices":["ROLLBACK : 데이터의 보안과 무결성을 정의한다.","COMMIT : 데이터베이스 사용자의 사용 권한을 취소한다.","GRANT : 데이터베이스 사용자의 사용 권한을 부여한다.","REVOKE : 데이터베이스 조작 작업이 비정상적으로 종료되었을 때 원래 상태로 복구한다."],"ans":3,"rate":79,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"DCL","url":"https://itwiki.kr/w/DCL"}],"exp":{"concept":"데이터 제어어(DCL, Data Control Language)는 데이터의 보안, 무결성, 회복, 병행 제어를 정의하는 명령어다. GRANT는 권한 부여, REVOKE는 권한 취소, COMMIT은 작업 결과를 확정, ROLLBACK은 작업을 취소하고 원래 상태로 되돌린다.","choices":[{"verdict":"오답","why":"ROLLBACK은 데이터베이스 조작 작업이 비정상적으로 끝났을 때 원래 상태로 복구하는 명령이다. 보기는 DCL 전체에 대한 설명이다."},{"verdict":"오답","why":"COMMIT은 트랜잭션 작업이 정상적으로 끝났을 때 그 결과를 데이터베이스에 반영하는 명령이다. 권한 취소는 REVOKE다."},{"verdict":"정답","why":"GRANT는 데이터베이스 사용자에게 사용 권한을 부여하는 명령이다. 바른 설명이다."},{"verdict":"오답","why":"REVOKE는 사용자의 사용 권한을 취소하는 명령이다. 원래 상태로 복구하는 것은 ROLLBACK이다."}],"keywords":[{"term":"GRANT","desc":"사용 권한 부여"},{"term":"REVOKE","desc":"사용 권한 취소"},{"term":"COMMIT","desc":"작업 결과를 데이터베이스에 확정 반영"},{"term":"ROLLBACK","desc":"비정상 종료 시 작업 전 상태로 복구"}],"memo":"보기 2번과 4번은 COMMIT·ROLLBACK·REVOKE의 설명을 서로 뒤섞어 놓았다. 짝을 정확히 외우자."}},{"id":"written-2022-1-57","no":57,"unit":"데이터베이스 구축","q":"테이블 R과 S에 대한 SQL문이 실행되었을 때, 실행결과로 옳은 것은?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<div class=\"q-tbl-title\">[릴레이션 R]</div><table class=\"q-tbl is-data\"><thead><tr><th>A</th><th>B</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr><tr><td>3</td><td>B</td></tr></tbody></table>\n<div class=\"q-tbl-title\">[릴레이션 S]</div><table class=\"q-tbl is-data\"><thead><tr><th>A</th><th>B</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr><tr><td>2</td><td>B</td></tr></tbody></table>\n<pre class=\"q-sql\"><code class=\"language-sql\">SELECT A FROM R\nUNION ALL\nSELECT A FROM S;</code></pre>\n</div>","choices":["<table class=\"q-tbl is-data\"><tbody><tr><td>1</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><tbody><tr><td>3</td></tr><tr><td>2</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><tbody><tr><td>1</td></tr><tr><td>3</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><tbody><tr><td>1</td></tr><tr><td>3</td></tr><tr><td>1</td></tr><tr><td>2</td></tr></tbody></table>"],"ans":4,"rate":82,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"UNION ALL은 두 SELECT 결과를 위아래로 그대로 이어 붙인다. UNION과 달리 중복 행을 지우지 않는다. R의 A열 결과(1, 3) 아래에 S의 A열 결과(1, 2)를 붙이면 1, 3, 1, 2의 네 행이 된다.","choices":[{"verdict":"오답","why":"1 한 행만 나오는 것은 두 결과의 공통 행만 남기는 INTERSECT의 결과다."},{"verdict":"오답","why":"3, 2는 두 결과 중 한쪽에만 있는 값만 모은 것으로, UNION ALL의 결과가 아니다."},{"verdict":"오답","why":"1, 3은 SELECT A FROM R만 실행했을 때의 결과다. S의 행이 빠졌다."},{"verdict":"정답","why":"R의 결과 1, 3 뒤에 S의 결과 1, 2가 중복 제거 없이 이어 붙어 1, 3, 1, 2가 된다."}],"keywords":[{"term":"UNION","desc":"두 결과를 합치고 중복 행은 한 번만 출력"},{"term":"UNION ALL","desc":"두 결과를 중복까지 모두 합쳐 출력"},{"term":"INTERSECT","desc":"두 결과의 공통 행만 출력"},{"term":"EXCEPT(MINUS)","desc":"앞 결과에서 뒤 결과에 있는 행을 뺀 나머지 출력"}],"memo":"ALL이 붙으면 '전부 다'. 중복도 지우지 않는다."}},{"id":"written-2022-1-58","no":58,"unit":"데이터베이스 구축","q":"분산 데이터베이스 시스템(Distributed Database System)에 대한 설명으로 틀린 것은?","choices":["분산 데이터베이스는 논리적으로는 하나의 시스템에 속하지만 물리적으로는 여러 개의 컴퓨터 사이트에 분산되어 있다.","위치 투명성, 중복 투명성, 병행 투명성, 장애 투명성을 목표로 한다.","데이터베이스의 설계가 비교적 어렵고, 개발 비용과 처리 비용이 증가한다는 단점이 있다.","분산 데이터베이스 시스템의 주요 구성 요소는 분산 처리기, P2P 시스템, 단일 데이터베이스 등이 있다."],"ans":4,"rate":56,"wiki":[{"title":"분산 데이터베이스","url":"https://itwiki.kr/w/분산 데이터베이스"}],"exp":{"concept":"분산 데이터베이스는 논리적으로는 하나의 데이터베이스지만, 실제 데이터는 네트워크로 연결된 여러 컴퓨터(사이트)에 나뉘어 저장된 시스템이다. 구성 요소는 분산 처리기, 분산 데이터베이스, 통신 네트워크이고, 사용자가 분산을 느끼지 못하도록 위치·중복·병행·장애 투명성을 목표로 한다.","choices":[{"verdict":"오답","why":"분산 데이터베이스는 논리적으로 하나의 시스템이지만 물리적으로는 여러 사이트에 분산되어 있다. 맞는 설명이다."},{"verdict":"오답","why":"위치 투명성, 중복 투명성, 병행 투명성, 장애 투명성을 목표로 한다. 맞는 설명이다."},{"verdict":"오답","why":"설계가 어렵고 소프트웨어 개발 비용과 처리 비용이 늘어나는 단점이 있다. 맞는 설명이다."},{"verdict":"정답","why":"분산 데이터베이스 시스템의 구성 요소는 분산 처리기, 분산 데이터베이스, 통신 네트워크다. P2P 시스템이나 단일 데이터베이스는 구성 요소가 아니므로 틀린 설명이다."}],"keywords":[{"term":"분산 DB 구성 요소","desc":"분산 처리기, 분산 데이터베이스, 통신 네트워크"},{"term":"분산 DB 투명성","desc":"위치, 중복(복제), 병행, 장애 투명성"},{"term":"위치 투명성","desc":"데이터가 실제 어디 있는지 몰라도 논리적 이름만으로 접근 가능"}],"memo":"'분산'인데 '단일 데이터베이스'가 구성 요소라는 말은 앞뒤가 안 맞는다."}},{"id":"written-2022-1-59","no":59,"unit":"데이터베이스 구축","q":"테이블 두 개를 조인하여 뷰 V_1을 정의하고, V_1을 이용하여 뷰 V_2를 정의하였다. 다음 명령 수행 후 결과로 옳은 것은?\n<img src=\"data/img/eip_written_20220305_059.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["V_1만 삭제된다.","V_2만 삭제된다.","V_1과 V_2 모두 삭제된다.","V_1과 V_2 모두 삭제되지 않는다."],"ans":3,"rate":82,"wiki":[{"title":"참조 무결성 제약","url":"https://itwiki.kr/w/참조 무결성 제약"},{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"DROP VIEW로 뷰를 삭제할 때 CASCADE를 붙이면, 삭제할 뷰를 참조하는 다른 뷰까지 연쇄적으로 함께 삭제된다. V_2는 V_1을 이용해 정의되었으므로 DROP VIEW V_1 CASCADE; 를 실행하면 V_1과 V_2가 모두 삭제된다.","choices":[{"verdict":"오답","why":"CASCADE 옵션은 참조하는 객체까지 함께 지우므로 V_1만 삭제되는 것이 아니다."},{"verdict":"오답","why":"삭제 대상은 V_1이며, V_2는 V_1을 참조하기 때문에 함께 삭제되는 것이다. V_2만 남는 일도, V_2만 삭제되는 일도 없다."},{"verdict":"정답","why":"CASCADE에 따라 V_1이 삭제되고, V_1을 참조하는 V_2도 연쇄적으로 삭제된다."},{"verdict":"오답","why":"모두 삭제되지 않는 경우는 RESTRICT 옵션을 썼을 때, 다른 뷰가 참조하고 있어 삭제가 거부되는 경우다."}],"keywords":[{"term":"CASCADE","desc":"삭제 대상을 참조하는 다른 객체까지 연쇄 삭제"},{"term":"RESTRICT","desc":"다른 객체가 참조 중이면 삭제를 거부"},{"term":"DROP VIEW","desc":"뷰 정의를 삭제하는 DDL 명령"}],"memo":"CASCADE는 '폭포처럼 줄줄이'. 참조하는 것까지 줄줄이 지워진다."}},{"id":"written-2022-1-60","no":60,"unit":"데이터베이스 구축","q":"데이터베이스에서 병행제어의 목적으로 틀린 것은?","choices":["시스템 활용도 최대화","사용자에 대한 응답시간 최소화","데이터베이스 공유 최소화","데이터베이스 일관성 유지"],"ans":3,"rate":72,"exp":{"concept":"병행 제어(Concurrency Control)는 여러 트랜잭션이 동시에 실행되어도 데이터베이스가 일관성을 유지하도록 실행 순서를 조절하는 기법이다. 목적은 데이터베이스 공유와 시스템 활용도를 최대화하고, 사용자 응답 시간은 최소화하며, 일관성을 유지하는 것이다.","choices":[{"verdict":"오답","why":"여러 트랜잭션을 동시에 실행해 시스템 활용도를 최대화하는 것이 병행 제어의 목적이다."},{"verdict":"오답","why":"동시에 처리해 사용자에 대한 응답 시간을 최소화하는 것이 목적이다."},{"verdict":"정답","why":"병행 제어의 목적은 데이터베이스 공유를 최대화하는 것이다. 공유를 최소화한다는 것은 틀렸다."},{"verdict":"오답","why":"동시 실행 중에도 데이터베이스의 일관성을 유지하는 것이 목적이다."}],"keywords":[{"term":"병행 제어 목적","desc":"DB 공유 최대화, 시스템 활용도 최대화, 응답 시간 최소화, 일관성 유지"},{"term":"병행 제어 기법","desc":"로킹(Locking), 타임 스탬프 순서, 최적 병행 수행, 다중 버전 기법"},{"term":"병행 제어 미보장 문제","desc":"갱신 분실, 비완료 의존성, 모순성, 연쇄 복귀"}],"memo":"병행 제어는 '여럿이 함께 쓰기' 위한 기술이다. 공유를 줄인다는 보기는 목적과 반대다."}},{"id":"written-2022-1-61","no":61,"unit":"프로그래밍 언어 활용","q":"IP 주소체계와 관련한 설명으로 틀린 것은?","choices":["IPv6의 패킷 헤더는 32 octet의 고정된 길이를 가진다.","IPv6는 주소 자동설정(Auto Configuration) 기능을 통해 손쉽게 이용자의 단말을 네트워크에 접속시킬 수 있다.","IPv4는 호스트 주소를 자동으로 설정하며 유니캐스트(Unicast)를 지원한다.","IPv4는 클래스별로 네트워크와 호스트 주소의 길이가 다르다."],"ans":1,"rate":65,"wiki":[{"title":"IPv4","url":"https://itwiki.kr/w/IPv4"},{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv4는 32비트 주소를 A~E 클래스로 나누어 쓰고, IPv6는 주소 부족 문제를 해결하려고 만든 128비트 주소 체계다. IPv6의 기본 헤더는 40옥텟(바이트)의 고정 길이이며, 부가 기능은 확장 헤더로 덧붙인다. 또 주소 자동 설정 기능으로 단말을 쉽게 네트워크에 연결할 수 있다.","choices":[{"verdict":"정답","why":"IPv6의 기본 패킷 헤더는 40옥텟(40바이트)의 고정 길이다. 32옥텟이라는 설명은 틀렸다."},{"verdict":"오답","why":"IPv6는 주소 자동 설정(Auto Configuration) 기능으로 사용자의 단말을 손쉽게 네트워크에 접속시킬 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"IPv4도 DHCP 등을 이용해 호스트 주소를 자동으로 설정할 수 있고, 유니캐스트·멀티캐스트·브로드캐스트를 지원한다. 틀린 설명으로 보지 않는다."},{"verdict":"오답","why":"IPv4는 A, B, C 클래스별로 네트워크 부분과 호스트 부분의 길이가 다르다. 맞는 설명이다."}],"keywords":[{"term":"IPv4","desc":"32비트, 8비트씩 4부분 10진수 표기, 클래스 A~E"},{"term":"IPv6","desc":"128비트, 16비트씩 8부분 16진수 표기, 기본 헤더 40바이트 고정"},{"term":"IPv6 주소 유형","desc":"유니캐스트, 멀티캐스트, 애니캐스트(브로드캐스트 없음)"}],"memo":"IPv6 헤더는 '40바이트 고정'. 32는 IPv4 주소의 비트 수이니 헤더 길이와 헷갈리지 말자."}},{"id":"written-2022-1-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220305_062.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["7, 5","8, 5","8, 9","7, 9"],"ans":3,"rate":62,"exp":{"concept":"int (*p)[3]은 '정수 3개짜리 배열'을 가리키는 포인터다. p = arr; 이면 p[0]은 arr[0] 행, p[1]은 arr[1] 행을 가리킨다. p[0]+1은 arr[0][1]의 주소, *(p+1)은 p[1]과 같은 arr[1] 행이므로 *(*(p+1)+0)은 arr[1][0]이다. arr는 {1,2,3}, {4,5,6}의 2행 3열 배열이다.","choices":[{"verdict":"오답","why":"첫 번째 값은 arr[0][1] + arr[1][2] = 2 + 6 = 8이므로 7이 아니다."},{"verdict":"오답","why":"첫 값 8은 맞지만, 두 번째 값은 arr[1][0] + arr[1][1] = 4 + 5 = 9이므로 5가 아니다."},{"verdict":"정답","why":"*(p[0]+1)은 arr[0][1] = 2, *(p[1]+2)는 arr[1][2] = 6이라 합은 8이다. *(*(p+1)+0)은 arr[1][0] = 4, *(*(p+1)+1)은 arr[1][1] = 5라 합은 9다. 출력은 8, 9다."},{"verdict":"오답","why":"첫 값은 2 + 6 = 8이므로 7이 아니다."}],"keywords":[{"term":"배열 포인터 int (*p)[3]","desc":"열이 3개인 행 하나를 통째로 가리키는 포인터, p+1은 다음 행"},{"term":"*(p[i]+j)","desc":"arr[i][j]와 같음"},{"term":"*(*(p+i)+j)","desc":"arr[i][j]와 같음, *(p+i)는 p[i]"}],"memo":"*(*(p+i)+j)는 그냥 arr[i][j]로 바꿔 읽으면 된다. 인덱스는 0부터 센다."}},{"id":"written-2022-1-63","no":63,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 중 데이터링크 계층에 해당되는 프로토콜이 아닌 것은?","choices":["HTTP","HDLC","PPP","LLC"],"ans":1,"rate":64,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"},{"title":"데이터링크 계층","url":"https://itwiki.kr/w/데이터링크 계층"},{"title":"프로토콜","url":"https://itwiki.kr/w/프로토콜"}],"exp":{"concept":"OSI 7계층 중 데이터 링크 계층(2계층)은 인접한 두 노드 사이에서 프레임을 오류 없이 전달하도록 흐름 제어와 오류 제어를 담당한다. 대표 프로토콜은 HDLC, PPP, LLC, MAC, LAPB, ATM, 이더넷 등이다. HTTP는 웹 문서를 주고받는 응용 계층(7계층) 프로토콜이다.","choices":[{"verdict":"정답","why":"HTTP(HyperText Transfer Protocol)는 웹 문서를 주고받는 응용 계층 프로토콜이다. 데이터 링크 계층이 아니다."},{"verdict":"오답","why":"HDLC(High-level Data Link Control)는 비트 위주의 데이터 링크 제어 프로토콜이다."},{"verdict":"오답","why":"PPP(Point-to-Point Protocol)는 두 지점을 직접 연결할 때 쓰는 데이터 링크 계층 프로토콜이다."},{"verdict":"오답","why":"LLC(Logical Link Control)는 데이터 링크 계층의 상위 부계층으로, 흐름 제어와 오류 제어를 담당한다."}],"keywords":[{"term":"데이터 링크 계층 프로토콜","desc":"HDLC, PPP, LLC, MAC, LAPB, 이더넷"},{"term":"네트워크 계층 프로토콜","desc":"IP, ICMP, ARP, RARP, IGMP"},{"term":"응용 계층 프로토콜","desc":"HTTP, FTP, SMTP, DNS, TELNET, SNMP"}],"memo":"OSI 7계층은 '물데네전세표응'. HTTP처럼 사용자가 직접 쓰는 서비스는 맨 위 응용 계층이다."}},{"id":"written-2022-1-64","no":64,"unit":"프로그래밍 언어 활용","q":"C언어에서 두 개의 논리 값 중 하나라도 참이면 1을, 모두 거짓이면 0을 반환하는 연산자는?","choices":["||","&&","**","!="],"ans":1,"rate":71,"exp":{"concept":"C언어의 논리 연산자에는 &&(AND), ||(OR), !(NOT)이 있다. ||는 두 값 중 하나라도 참이면 1, 둘 다 거짓이면 0을 돌려준다. &&는 둘 다 참일 때만 1을 돌려준다.","choices":[{"verdict":"정답","why":"||는 논리합(OR) 연산자로, 둘 중 하나라도 참이면 1, 모두 거짓이면 0을 반환한다."},{"verdict":"오답","why":"&&는 논리곱(AND) 연산자로, 두 값이 모두 참일 때만 1을 반환한다."},{"verdict":"오답","why":"C언어에는 두 값을 계산하는 ** 연산자가 없다(**p처럼 포인터 앞에 붙은 것은 간접 참조 *를 두 번 쓴 것이다). Python에서는 거듭제곱 연산자로 쓰인다."},{"verdict":"오답","why":"!=는 두 값이 다르면 1, 같으면 0을 반환하는 관계 연산자다."}],"keywords":[{"term":"&&","desc":"논리 AND, 모두 참이어야 1"},{"term":"||","desc":"논리 OR, 하나라도 참이면 1"},{"term":"!","desc":"논리 NOT, 참과 거짓을 뒤집음"},{"term":"!=","desc":"관계 연산자, 같지 않으면 1"}],"memo":"하나라도 참이면 OR(||), 모두 참이어야 AND(&&)."}},{"id":"written-2022-1-65","no":65,"unit":"프로그래밍 언어 활용","q":"IPv6에 대한 특성으로 틀린 것은?","choices":["표시방법은 8비트씩 4부분의 10진수로 표시한다.","2<sup>128</sup>개의 주소를 표현할 수 있다.","등급별, 서비스별로 패킷을 구분할 수 있어 품질보장이 용이하다.","확장기능을 통해 보안기능을 제공한다."],"ans":1,"rate":71,"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv6는 128비트 주소 체계로, 16비트씩 8부분으로 나누어 16진수로 표시하고 콜론(:)으로 구분한다. 2의 128제곱 개의 주소를 쓸 수 있고, 트래픽 클래스와 흐름 레이블로 패킷을 구분해 서비스 품질(QoS)을 보장하기 쉬우며, 확장 헤더로 보안(IPSec) 기능을 제공한다.","choices":[{"verdict":"정답","why":"8비트씩 4부분을 10진수로 표시하는 것은 IPv4다. IPv6는 16비트씩 8부분을 16진수로 표시한다. 틀린 설명이다."},{"verdict":"오답","why":"128비트 주소이므로 2의 128제곱(2^128)개의 주소를 표현할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"트래픽 클래스, 흐름 레이블로 등급별·서비스별로 패킷을 구분할 수 있어 품질 보장이 쉽다. 맞는 설명이다."},{"verdict":"오답","why":"확장 헤더를 통해 인증·암호화 같은 보안 기능을 제공한다. 맞는 설명이다."}],"keywords":[{"term":"IPv6 표기","desc":"16비트씩 8부분, 16진수, 콜론(:)으로 구분"},{"term":"IPv4 표기","desc":"8비트씩 4부분, 10진수, 점(.)으로 구분"},{"term":"IPv6 장점","desc":"주소 공간 확대, 자동 설정, QoS 보장 용이, 보안(IPSec) 강화"}],"memo":"IPv4는 '8비트 4개, 10진수, 점', IPv6는 '16비트 8개, 16진수, 콜론'. 짝으로 외우자."}},{"id":"written-2022-1-66","no":66,"unit":"프로그래밍 언어 활용","q":"JAVA의 예외(exception)와 관련한 설명으로 틀린 것은?","choices":["문법 오류로 인해 발생한 것","오동작이나 결과에 악영향을 미칠 수 있는 실행 시간 동안에 발생한 오류","배열의 인덱스가 그 범위를 넘어서는 경우 발생하는 오류","존재하지 않는 파일을 읽으려고 하는 경우에 발생하는 오류"],"ans":1,"rate":62,"exp":{"concept":"Java의 예외(Exception)는 프로그램이 실행되는 동안 발생해 정상 흐름을 방해하는 오류다. 배열 인덱스가 범위를 벗어나거나, 없는 파일을 읽으려고 할 때 등이 예다. 문법 오류는 실행 전에 컴파일 단계에서 걸러지는 컴파일 오류이므로 예외가 아니다.","choices":[{"verdict":"정답","why":"문법 오류는 컴파일할 때 발견되는 컴파일 오류로, 실행 중에 발생하는 예외가 아니다. 틀린 설명이다."},{"verdict":"오답","why":"예외는 실행 시간 동안 발생해 오동작이나 결과에 악영향을 줄 수 있는 오류다. 맞는 설명이다."},{"verdict":"오답","why":"배열 인덱스가 범위를 넘으면 ArrayIndexOutOfBoundsException 예외가 발생한다. 맞는 설명이다."},{"verdict":"오답","why":"존재하지 않는 파일을 읽으려 하면 FileNotFoundException 예외가 발생한다. 맞는 설명이다."}],"keywords":[{"term":"예외(Exception)","desc":"실행 중 발생하는 오류, try-catch로 처리 가능"},{"term":"ArrayIndexOutOfBoundsException","desc":"배열 인덱스 범위 초과"},{"term":"FileNotFoundException","desc":"존재하지 않는 파일에 접근"},{"term":"컴파일 오류","desc":"문법이 틀려 컴파일 단계에서 발견되는 오류"}],"memo":"예외는 '실행 중' 오류다. '문법 오류'는 실행 전에 걸리므로 예외가 아니다."}},{"id":"written-2022-1-67","no":67,"unit":"프로그래밍 언어 활용","q":"TCP/IP 계층 구조에서 IP의 동작 과정에서의 전송 오류가 발생하는 경우에 대비해 오류 정보를 전송하는 목적으로 사용하는 프로토콜은?","choices":["ECP(Error Checking Protocol)","ARP(Address Resolution Protocol)","ICMP(Internet Control Message Protocol)","PPP(Point-to-Point Protocol)"],"ans":3,"rate":53,"wiki":[{"title":"TCP/IP","url":"https://itwiki.kr/w/TCP/IP"},{"title":"ARP","url":"https://itwiki.kr/w/ARP"},{"title":"ICMP","url":"https://itwiki.kr/w/ICMP"},{"title":"PPP","url":"https://itwiki.kr/w/PPP"}],"exp":{"concept":"IP는 데이터를 목적지까지 보내는 역할만 할 뿐, 오류가 나도 스스로 알려 주지 못한다. 그래서 전송 중 오류가 생기면 오류 정보나 제어 메시지를 보내 주는 프로토콜이 따로 있는데, 이것이 ICMP다. ping 명령도 ICMP를 이용한다.","choices":[{"verdict":"오답","why":"ECP(Error Checking Protocol)는 출제 범위의 표준 프로토콜이 아니다."},{"verdict":"오답","why":"ARP(Address Resolution Protocol)는 IP 주소를 물리 주소(MAC 주소)로 바꿔 주는 프로토콜이다."},{"verdict":"정답","why":"ICMP(Internet Control Message Protocol)는 IP 전송 과정에서 오류가 생기면 오류 정보와 제어 메시지를 전송하는 프로토콜이다."},{"verdict":"오답","why":"PPP(Point-to-Point Protocol)는 두 지점을 직접 연결하는 데이터 링크 계층 프로토콜이다."}],"keywords":[{"term":"ICMP","desc":"IP 전송 오류 정보·제어 메시지 전달, ping이 사용"},{"term":"ARP","desc":"IP 주소를 MAC 주소로 변환"},{"term":"RARP","desc":"MAC 주소를 IP 주소로 변환"},{"term":"IGMP","desc":"멀티캐스트 그룹 관리"}],"memo":"ICMP의 C·M은 Control Message. 오류·제어 '메시지'를 보내면 ICMP."}},{"id":"written-2022-1-68","no":68,"unit":"프로그래밍 언어 활용","q":"좋은 소프트웨어 설계를 위한 소프트웨어의 모듈간의 결합도(Coupling)와 모듈 내 요소 간 응집도(Cohesion)에 대한 설명으로 옳은 것은?","choices":["응집도는 낮게 결합도는 높게 설계한다.","응집도는 높게 결합도는 낮게 설계한다.","양쪽 모두 낮게 설계한다.","양쪽 모두 높게 설계한다."],"ans":2,"rate":84,"exp":{"concept":"결합도(Coupling)는 모듈과 모듈이 서로 얼마나 얽혀 있는지, 응집도(Cohesion)는 한 모듈 안의 요소들이 얼마나 하나의 목적으로 똘똘 뭉쳐 있는지를 나타낸다. 좋은 설계는 모듈끼리는 느슨하게(결합도 낮게), 모듈 안은 단단하게(응집도 높게) 만든다. 그래야 한 모듈을 고쳐도 다른 모듈에 영향이 적다.","choices":[{"verdict":"오답","why":"응집도가 낮고 결합도가 높으면 모듈 하나를 고칠 때 다른 모듈까지 줄줄이 영향을 받는 나쁜 설계가 된다."},{"verdict":"정답","why":"응집도는 높게, 결합도는 낮게 설계하는 것이 독립성이 높은 좋은 모듈 설계다."},{"verdict":"오답","why":"응집도까지 낮으면 모듈 안의 요소들이 서로 관련 없이 흩어져 있어 좋은 설계가 아니다."},{"verdict":"오답","why":"결합도까지 높으면 모듈 사이의 의존이 커져 유지보수가 어려워진다."}],"keywords":[{"term":"결합도(약 → 강)","desc":"자료 < 스탬프 < 제어 < 외부 < 공통 < 내용"},{"term":"응집도(강 → 약)","desc":"기능 > 순차 > 교환 > 절차 > 시간 > 논리 > 우연"},{"term":"모듈 독립성","desc":"결합도는 낮고 응집도는 높을수록 높아짐"}],"memo":"'결낮응높'. 결합은 낮게, 응집은 높게."}},{"id":"written-2022-1-69","no":69,"unit":"프로그래밍 언어 활용","q":"다음과 같은 형태로 임계 구역의 접근을 제어하는 상호배제 기법은?\n<img src=\"data/img/eip_written_20220305_069.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Dekker Algorithm","Lamport Algorithm","Peterson Algorithm","Semaphore"],"ans":4,"rate":56,"wiki":[{"title":"세마포어","url":"https://itwiki.kr/w/세마포어"}],"exp":{"concept":"세마포어(Semaphore)는 다익스트라(Dijkstra)가 제안한 상호 배제 기법으로, 정수 변수 S와 두 연산 P, V로 임계 구역 진입을 제어한다. P(S)는 S가 0 이하이면 기다렸다가 S를 1 줄이고 들어가며, V(S)는 임계 구역을 나오면서 S를 1 늘려 다른 프로세스가 들어올 수 있게 한다. 지문의 P(S), V(S) 형태가 결정적 단서다.","choices":[{"verdict":"오답","why":"Dekker 알고리즘은 두 프로세스의 상호 배제를 flag와 turn 변수로 해결한 소프트웨어 알고리즘으로, P·V 연산을 쓰지 않는다."},{"verdict":"오답","why":"Lamport 알고리즘은 빵집(Bakery) 알고리즘이라고도 하며, 번호표를 나눠 주고 작은 번호부터 임계 구역에 들어가게 하는 n개 프로세스용 상호 배제 기법이다."},{"verdict":"오답","why":"Peterson 알고리즘은 두 프로세스의 상호 배제를 flag와 turn 변수로 해결하는 간단한 소프트웨어 알고리즘이다."},{"verdict":"정답","why":"Semaphore는 P(S)에서 S가 0 이하이면 기다렸다가 S를 감소시키고, V(S)에서 S를 증가시키는 방식으로 임계 구역 접근을 제어한다. 지문과 일치한다."}],"keywords":[{"term":"세마포어(Semaphore)","desc":"다익스트라가 제안, P(Wait)·V(Signal) 연산으로 상호 배제"},{"term":"P 연산","desc":"자원을 얻을 때 S를 1 감소, S가 0 이하면 대기"},{"term":"V 연산","desc":"자원을 반납할 때 S를 1 증가"},{"term":"임계 구역(Critical Section)","desc":"한 번에 하나의 프로세스만 들어가야 하는 공유 자원 영역"}],"memo":"P는 들어갈 때(감소), V는 나올 때(증가). P와 V가 보이면 세마포어."}},{"id":"written-2022-1-70","no":70,"unit":"프로그래밍 언어 활용","q":"소프트웨어 개발에서 모듈(Module)이 되기 위한 주요 특징에 해당하지 않는 것은?","choices":["다른 것들과 구별될 수 있는 독립적인 기능을 가진 단위(Unit)이다.","독립적인 컴파일이 가능하다.","유일한 이름을 가져야 한다.","다른 모듈에서의 접근이 불가능해야 한다."],"ans":4,"rate":84,"exp":{"concept":"모듈(Module)은 프로그램을 기능별로 나눈 독립적인 단위다. 모듈은 고유한 이름을 갖고, 따로 컴파일할 수 있으며, 다른 모듈에서 호출해 사용할 수 있어야 한다. 다른 모듈이 전혀 접근할 수 없다면 그 모듈을 조립해 프로그램을 만들 수 없다.","choices":[{"verdict":"오답","why":"모듈은 다른 것과 구별되는 독립적인 기능을 가진 단위다. 모듈의 특징이다."},{"verdict":"오답","why":"모듈은 독립적으로 컴파일할 수 있다. 모듈의 특징이다."},{"verdict":"오답","why":"모듈은 다른 모듈과 구별되도록 유일한 이름을 가져야 한다. 모듈의 특징이다."},{"verdict":"정답","why":"모듈은 다른 모듈에서 호출(접근)해 사용할 수 있어야 한다. 접근이 불가능해야 한다는 것은 모듈의 특징이 아니다."}],"keywords":[{"term":"모듈(Module)","desc":"독립 기능 단위, 유일한 이름, 독립 컴파일 가능, 다른 모듈에서 호출 가능"},{"term":"모듈화","desc":"프로그램을 모듈 단위로 나누어 개발·유지보수를 쉽게 하는 것"}],"memo":"모듈은 '부품'이다. 부품끼리 연결이 안 되면 조립할 수 없다."}},{"id":"written-2022-1-71","no":71,"unit":"프로그래밍 언어 활용","q":"빈 기억공간의 크기가 20KB, 16KB, 8KB, 40KB 일 때 기억장치 배치 전략으로 “Best Fit\"을 사용하여 17KB의 프로그램을 적재할 경우 내부단편화의 크기는 얼마인가?","choices":["3KB","23KB","64KB","67KB"],"ans":1,"rate":79,"exp":{"concept":"최적 적합(Best Fit)은 프로그램이 들어갈 수 있는 빈 공간 중 남는 공간이 가장 작은 곳에 배치하는 전략이다. 17KB가 들어갈 수 있는 공간은 20KB와 40KB이고, 그중 더 작은 20KB에 넣는다. 그러면 20 - 17 = 3KB가 쓰이지 않고 남는데, 이것이 내부 단편화다.","choices":[{"verdict":"정답","why":"17KB 이상인 공간(20KB, 40KB) 중 가장 작은 20KB에 배치하므로 내부 단편화는 20 - 17 = 3KB다."},{"verdict":"오답","why":"23KB는 40KB 공간에 넣었을 때(40 - 17)의 단편화로, 가장 큰 공간에 넣는 최악 적합(Worst Fit)의 결과다."},{"verdict":"오답","why":"64KB는 프로그램이 들어가지 않은 나머지 공간(16 + 8 + 40)의 합으로, 내부 단편화가 아니다."},{"verdict":"오답","why":"67KB는 전체 빈 공간 84KB에서 17KB를 뺀 값으로, 내부 단편화가 아니다."}],"keywords":[{"term":"최초 적합(First Fit)","desc":"들어갈 수 있는 첫 번째 공간에 배치"},{"term":"최적 적합(Best Fit)","desc":"단편화가 가장 작게 남는 공간에 배치"},{"term":"최악 적합(Worst Fit)","desc":"단편화가 가장 크게 남는 공간에 배치"},{"term":"내부 단편화","desc":"할당된 공간 안에서 쓰이지 않고 남는 부분"}],"memo":"Best Fit은 '딱 맞는 옷', Worst Fit은 '제일 큰 옷'. 16KB처럼 작은 공간에는 아예 못 들어간다는 점도 확인하자."}},{"id":"written-2022-1-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 C언어프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220305_072.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["i = 0","i = 1","i = 3","i = 4"],"ans":4,"rate":76,"exp":{"concept":"while(1)은 조건이 항상 참인 무한 반복이라 break를 만나야만 빠져나온다. i는 0에서 시작해 반복할 때마다 ++i로 1씩 늘고, if(i==4)가 참이 되는 순간 break로 반복을 끝낸다. 따라서 반복이 끝난 뒤 i는 4다.","choices":[{"verdict":"오답","why":"i가 0일 때는 i==4가 거짓이라 break하지 않고 ++i로 1이 된다. 0에서 멈추지 않는다."},{"verdict":"오답","why":"i가 1일 때도 i==4가 거짓이므로 계속 증가한다."},{"verdict":"오답","why":"i가 3일 때 i==4가 거짓이라 ++i로 4가 된 뒤 다음 반복에서 검사한다. 3에서 멈추지 않는다."},{"verdict":"정답","why":"i는 0 → 1 → 2 → 3 → 4로 증가하고, i==4가 참이 되는 순간 break로 빠져나와 i = 4가 출력된다."}],"keywords":[{"term":"while(1)","desc":"조건이 항상 참인 무한 반복, break로 탈출"},{"term":"break","desc":"가장 가까운 반복문을 즉시 빠져나감"},{"term":"++i","desc":"전위 증가, 값을 먼저 1 증가"}],"memo":"반복 안에서 if(i==4) 검사가 ++i보다 먼저 온다. 검사 위치와 증가 위치를 순서대로 따라가자.","doubt":"지문 4행이 int i = 0 으로 세미콜론이 빠져 있어 그대로는 컴파일 오류다. 출제 의도(int i = 0;의 오타)로 보면 정답 i = 4가 맞다."}},{"id":"written-2022-1-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220305_073.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["BCDABCA","BCDABCC","CDDACCC","CDDACCA"],"ans":2,"rate":70,"exp":{"concept":"rs 함수는 배열을 0번부터 차례로 바꾸는데, 앞에서 바꾼 값이 뒤의 계산에 그대로 쓰인다는 점이 핵심이다. 'B'면 'C'로 바꾸고, 마지막 칸이면 바로 앞 칸 값을, 그 밖에는 바로 뒤 칸 값을 복사한다. 처음 배열은 A B D D A B C다.","choices":[{"verdict":"오답","why":"마지막 칸(i=6)은 바로 앞 칸 a[5]를 복사하는데, a[5]는 이미 'C'로 바뀌어 있으므로 마지막 글자는 A가 아니라 C다."},{"verdict":"정답","why":"i=0 A→a[1]인 B, i=1 B→C, i=2 D→a[3]인 D, i=3 D→a[4]인 A, i=4 A→a[5]인 B, i=5 B→C, i=6 마지막 칸이라 a[5]인 C를 복사한다. 결과는 BCDABCC다."},{"verdict":"오답","why":"첫 칸 a[0]은 a[1]인 'B'를 복사하므로 C로 시작할 수 없다."},{"verdict":"오답","why":"첫 칸 a[0]은 'B'가 되므로 C로 시작할 수 없다."}],"keywords":[{"term":"배열 원소 갱신 순서","desc":"앞에서 바뀐 값이 뒤 원소 계산에 그대로 반영됨"},{"term":"a.length","desc":"Java 배열의 길이, 마지막 인덱스는 a.length - 1"},{"term":"if-else if-else","desc":"위에서부터 처음 참인 조건 하나만 실행"}],"memo":"배열을 한 칸씩 바꾸는 문제는 표를 그려 '현재 배열 상태'를 매 단계 갱신하며 따라가자."}},{"id":"written-2022-1-74","no":74,"unit":"프로그래밍 언어 활용","q":"개발 환경 구성을 위한 빌드(Build) 도구에 해당하지 않는 것은?","choices":["Ant","Kerberos","Maven","Gradle"],"ans":2,"rate":73,"wiki":[{"title":"빌드","url":"https://itwiki.kr/w/빌드"},{"title":"커버로스","url":"https://itwiki.kr/w/커버로스"}],"exp":{"concept":"빌드 도구는 소스 코드를 컴파일하고, 필요한 라이브러리를 가져오고, 실행 파일로 묶는 과정을 자동화하는 도구다. 대표적인 것이 Ant, Maven, Gradle이다. Kerberos는 빌드와 관계없는 네트워크 인증 프로토콜이다.","choices":[{"verdict":"오답","why":"Ant는 Apache 재단의 XML 기반 Java 빌드 도구다."},{"verdict":"정답","why":"Kerberos는 티켓을 이용해 사용자를 인증하는 네트워크 인증 프로토콜이다. 빌드 도구가 아니다."},{"verdict":"오답","why":"Maven은 Apache 재단의 빌드 도구로, POM 파일로 프로젝트와 의존성(라이브러리)을 관리한다."},{"verdict":"오답","why":"Gradle은 Groovy(또는 Kotlin) 기반의 빌드 도구로, 안드로이드 앱 개발의 표준 빌드 도구로 쓰인다."}],"keywords":[{"term":"Ant","desc":"XML 기반 Java 빌드 도구"},{"term":"Maven","desc":"POM 기반 빌드·의존성 관리 도구"},{"term":"Gradle","desc":"Groovy 기반 빌드 도구, 안드로이드 표준"},{"term":"Kerberos","desc":"티켓 기반 네트워크 인증 프로토콜"},{"term":"Jenkins","desc":"Java 기반 오픈 소스 빌드 자동화 도구, 지속적 통합(CI) 환경에 주로 쓰임"}],"memo":"빌드 자동화 도구는 '앤트·메이븐·그래들·젠킨스(Ant·Maven·Gradle·Jenkins)'. Kerberos는 보안(인증) 쪽이다."}},{"id":"written-2022-1-75","no":75,"unit":"프로그래밍 언어 활용","q":"3개의 페이지 프레임을 갖는 시스템에서 페이지 참조 순서가 1, 2, 1, 0, 4, 1, 3 일 경우 FIFO 알고리즘에 의한 페이지 교체의 경우 프레임의 최종 상태는?","choices":["1, 2, 0","2, 4, 3","1, 4, 2","4, 1, 3"],"ans":4,"rate":79,"exp":{"concept":"FIFO(First In First Out) 페이지 교체는 메모리에 가장 먼저 들어온 페이지를 먼저 내보내는 방식이다. 프레임 3개로 1, 2, 1, 0, 4, 1, 3을 차례로 참조하면 1, 2, 0이 들어와 프레임이 찬 뒤 4가 1을, 1이 2를, 3이 0을 차례로 밀어낸다. 최종 상태는 4, 1, 3이다.","choices":[{"verdict":"오답","why":"1, 2, 0은 0을 참조한 직후의 상태로, 이후 4, 1, 3이 들어오며 교체가 세 번 더 일어난다."},{"verdict":"오답","why":"2는 4가 들어온 다음 1을 참조할 때 가장 오래된 페이지라 이미 교체되었으므로 최종 프레임에 남지 않는다."},{"verdict":"오답","why":"2는 1이 다시 들어올 때 밀려나므로 최종 프레임에 없고, 3이 마지막에 적재되어야 한다."},{"verdict":"정답","why":"1→[1], 2→[1,2], 1→적중, 0→[1,2,0], 4→가장 오래된 1 교체[4,2,0], 1→가장 오래된 2 교체[4,1,0], 3→가장 오래된 0 교체[4,1,3]. 최종 상태는 4, 1, 3이다."}],"keywords":[{"term":"FIFO","desc":"가장 먼저 들어온 페이지를 교체"},{"term":"LRU","desc":"가장 오랫동안 사용하지 않은 페이지를 교체"},{"term":"LFU","desc":"사용 횟수가 가장 적은 페이지를 교체"},{"term":"OPT","desc":"앞으로 가장 오랫동안 사용하지 않을 페이지를 교체"}],"memo":"FIFO에서 적중(hit)은 들어온 순서를 바꾸지 않는다. 다시 참조된 1도 여전히 가장 오래된 페이지다."}},{"id":"written-2022-1-76","no":76,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램이 실행되었을 때, 실행 결과는?\n<img src=\"data/img/eip_written_20220305_076.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["E","V","R","O"],"ans":3,"rate":65,"exp":{"concept":"p1, p2는 각각 str1, str2의 시작 주소를 가리키므로 p1[i]는 str1[i], p2[i]는 str2[i]와 같다. 처음 str1은 KOREA, str2는 LOVE다. str1[1] = p2[2]로 str1[1]이 'V'가 되어 KVREA, str2[3] = p1[4]로 str2[3]이 'A'가 되어 LOVA, strcat로 str1 뒤에 str2를 붙여 KVREALOVA가 된다. *(p1+2)는 str1[2]이다.","choices":[{"verdict":"오답","why":"E는 str2의 원래 3번 문자였으나 'A'로 바뀌었고, 출력 대상인 str1[2]와 관계없다."},{"verdict":"오답","why":"V는 바뀐 str1[1]이다. 출력하는 것은 str1[2]이므로 한 칸 뒤의 문자다."},{"verdict":"정답","why":"최종 str1은 KVREALOVA이고, *(p1+2)는 인덱스 2인 'R'이다."},{"verdict":"오답","why":"O는 str1의 원래 1번 문자였지만 'V'로 바뀌었고, 출력 대상도 아니다."}],"keywords":[{"term":"p[i]와 *(p+i)","desc":"포인터가 가리키는 배열의 i번 원소, 둘은 같은 표현"},{"term":"strcat(a, b)","desc":"문자열 a 끝에 문자열 b를 이어 붙임"},{"term":"%c","desc":"문자 하나를 출력하는 서식 지정자"}],"memo":"포인터는 배열의 별명이다. p1[2]로 바꿔 읽고, 인덱스 0부터 세자."}},{"id":"written-2022-1-77","no":77,"unit":"프로그래밍 언어 활용","q":"다음 Python 프로그램이 실행되었을 때, 실행 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<pre class=\"qcode\"><code class=\"language-python\">a = 100\nlist_data = ['a', 'b', 'c']\ndict_data = {'a': 90, 'b': 95}\nprint(list_data[0])\nprint(dict_data['a'])</code></pre>\n</div>","choices":["a<br>90","100<br>90","100<br>100","a<br>a"],"ans":1,"rate":86,"wiki":[{"title":"파이썬 리스트","url":"https://itwiki.kr/w/파이썬 리스트"},{"title":"파이썬 딕셔너리","url":"https://itwiki.kr/w/파이썬 딕셔너리"}],"exp":{"concept":"리스트는 대괄호 안에 인덱스(0부터 시작)를 넣어 원소를 꺼내고, 딕셔너리는 대괄호 안에 키를 넣어 값을 꺼낸다. list_data[0]은 첫 원소인 문자열 'a', dict_data['a']는 키 'a'의 값 90이다. 첫 줄의 a = 100은 출력에 쓰이지 않는다.","choices":[{"verdict":"정답","why":"print(list_data[0])은 첫 원소 'a'를, print(dict_data['a'])는 키 'a'의 값 90을 출력한다. 결과는 a와 90 두 줄이다."},{"verdict":"오답","why":"list_data[0]은 변수 a(100)가 아니라 리스트에 들어 있는 문자열 'a'다."},{"verdict":"오답","why":"list_data[0]은 문자열 'a'이고, dict_data['a']는 90이다. 100은 어디에도 출력되지 않는다."},{"verdict":"오답","why":"dict_data['a']는 키 'a'에 대응하는 값 90을 꺼내므로 a가 출력되지 않는다."}],"keywords":[{"term":"리스트 인덱싱","desc":"list[0]은 첫 번째 원소"},{"term":"딕셔너리 조회","desc":"dict[키]는 그 키에 대응하는 값"},{"term":"문자열 'a'와 변수 a","desc":"따옴표가 있으면 문자열 값, 없으면 변수 이름"}],"memo":"따옴표 안의 'a'는 변수 a와 아무 관계가 없다. 미끼 변수에 속지 말자."}},{"id":"written-2022-1-78","no":78,"unit":"프로그래밍 언어 활용","q":"C언어에서 정수 변수 a, b에 각각 1, 2가 저장되어 있을 때 다음 식의 연산 결과로 옳은 것은?\n<img src=\"data/img/eip_written_20220305_078.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["0","1","3","5"],"ans":2,"rate":62,"exp":{"concept":"C언어 연산자는 우선순위대로 계산한다. 산술(+) → 시프트(<<) → 관계(<, <=) → 논리(&&) 순서다. 그래서 식은 (a < (b + 2)) && ((a << 1) <= b)로 묶인다. a = 1, b = 2를 넣어 차례로 계산하면 된다.","choices":[{"verdict":"오답","why":"&& 양쪽이 모두 참(1)이므로 결과는 0이 아니다."},{"verdict":"정답","why":"b + 2 = 4, a < 4는 1 < 4라 참(1). a << 1은 1을 왼쪽으로 1비트 밀어 2, 2 <= 2는 참(1). 1 && 1 = 1이다."},{"verdict":"오답","why":"관계·논리 연산의 결과는 참이면 1, 거짓이면 0뿐이므로 3이 나올 수 없다."},{"verdict":"오답","why":"&&의 결과는 0 또는 1이므로 5가 나올 수 없다."}],"keywords":[{"term":"C 연산자 우선순위","desc":"단항 > 산술(* / % > + -) > 시프트 > 관계 > 비트 > 논리(&& > ||) > 조건 > 대입"},{"term":"<< (왼쪽 시프트)","desc":"비트를 왼쪽으로 n칸 이동, 값이 2의 n제곱 배"},{"term":"논리·관계 연산 결과","desc":"참은 1, 거짓은 0"}],"memo":"'산시관논'(산술-시프트-관계-논리) 순서로 괄호를 쳐 놓고 계산하자."}},{"id":"written-2022-1-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음 Python 프로그램이 실행되었을 때, 실행 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<pre class=\"qcode\"><code class=\"language-python\">a = [\"대\", \"한\", \"민\", \"국\"]\nfor i in a:\n    print(i)</code></pre>\n</div>","choices":["대한민국","대<br>한<br>민<br>국","대","대대대대"],"ans":2,"rate":72,"exp":{"concept":"Python의 for i in a: 는 리스트 a의 원소를 앞에서부터 하나씩 꺼내 i에 넣고 반복한다. print()는 출력한 뒤 자동으로 줄을 바꾸므로, 네 원소가 한 줄에 하나씩 네 줄로 출력된다.","choices":[{"verdict":"오답","why":"대한민국처럼 한 줄로 붙여 출력하려면 print(i, end='')처럼 줄바꿈을 없애야 한다."},{"verdict":"정답","why":"for 문이 '대', '한', '민', '국'을 차례로 꺼내고, print가 매번 줄을 바꾸므로 네 줄로 출력된다."},{"verdict":"오답","why":"반복은 원소 수만큼 네 번 일어나므로 '대' 하나만 출력되지 않는다."},{"verdict":"오답","why":"i에는 매번 다음 원소가 들어가므로 '대'만 반복되지 않는다."}],"keywords":[{"term":"for 변수 in 리스트","desc":"리스트 원소를 하나씩 꺼내 반복"},{"term":"print()","desc":"기본적으로 출력 뒤 줄바꿈(end='\\n')"},{"term":"end 인자","desc":"print(x, end='')처럼 줄바꿈 대신 다른 문자를 출력"}],"memo":"print의 기본 end는 줄바꿈이다. end가 없으면 원소마다 한 줄씩 출력된다."}},{"id":"written-2022-1-80","no":80,"unit":"프로그래밍 언어 활용","q":"UNIX 시스템의 쉘(shell)의 주요 기능에 대한 설명이 아닌 것은?","choices":["사용자 명령을 해석하고 커널로 전달하는 기능을 제공한다.","반복적인 명령 프로그램을 만드는 프로그래밍 기능을 제공한다.","쉘 프로그램 실행을 위해 프로세스와 메모리를 관리한다.","초기화 파일을 이용해 사용자 환경을 설정하는 기능을 제공한다."],"ans":3,"rate":53,"wiki":[{"title":"Shell","url":"https://itwiki.kr/w/Shell"}],"exp":{"concept":"쉘(Shell)은 사용자가 입력한 명령을 해석해 커널에 전달하는 명령어 해석기다. 여러 명령을 묶어 쉘 스크립트를 만드는 프로그래밍 기능과, 초기화 파일(.profile, .bashrc 등)로 사용자 환경을 설정하는 기능도 있다. 프로세스와 메모리를 관리하는 일은 쉘이 아니라 커널(Kernel)의 역할이다.","choices":[{"verdict":"오답","why":"사용자 명령을 해석해 커널로 전달하는 것은 쉘의 핵심 기능이다."},{"verdict":"오답","why":"반복적인 명령을 묶어 쉘 스크립트로 만드는 프로그래밍 기능을 제공한다."},{"verdict":"정답","why":"프로세스 관리와 메모리 관리는 커널(Kernel)의 기능이다. 쉘의 기능이 아니다."},{"verdict":"오답","why":"초기화 파일을 이용해 사용자 환경을 설정하는 기능을 제공한다."}],"keywords":[{"term":"쉘(Shell)","desc":"명령어 해석기, 사용자와 커널 사이의 인터페이스"},{"term":"커널(Kernel)","desc":"UNIX의 핵심, 프로세스·메모리·파일·입출력 관리"},{"term":"쉘 종류","desc":"Bourne shell(sh), C shell(csh), Korn shell(ksh), Bash"}],"memo":"쉘은 '통역사', 커널은 '실제로 일하는 관리자'. 프로세스·메모리 관리는 커널."}},{"id":"written-2022-1-81","no":81,"unit":"정보시스템 구축 관리","q":"소프트웨어 생명주기 모델 중 나선형 모델(Spiral Model)과 관련한 설명으로 틀린 것은??","choices":["소프트웨어 개발 프로세스를 위험 관리(Risk Management) 측면에서 본 모델이다.","위험 분석(Risk Analysis)은 반복적인 개발 진행 후 주기의 마지막 단계에서 최종적으로 한 번 수행해야 한다.","시스템을 여러 부분으로 나누어 여러 번의 개발 주기를 거치면서 시스템이 완성된다.","요구사항이나 아키텍처를 이해하기 어렵다거나 중심이 되는 기술에 문제가 있는 경우 적합한 모델이다."],"ans":2,"rate":76,"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"exp":{"concept":"나선형 모델(Spiral Model)은 보헴(Boehm)이 제안한 모델로, 계획 수립 → 위험 분석 → 개발 및 검증 → 고객 평가를 여러 번 반복하면서 점점 완성도를 높인다. 반복할 때마다 위험을 분석해 줄여 나가는 것이 핵심이다. 달팽이 껍데기처럼 같은 단계를 돌며 점점 커지는 모양이다.","choices":[{"verdict":"오답","why":"나선형 모델은 위험 관리(Risk Management)를 중심으로 개발 과정을 본 모델이다. 맞는 설명이다."},{"verdict":"정답","why":"위험 분석은 마지막에 한 번만 하는 것이 아니라 매 반복 주기마다 수행한다. 틀린 설명이다."},{"verdict":"오답","why":"시스템을 여러 부분으로 나누어 여러 번의 개발 주기를 거치며 완성해 간다. 맞는 설명이다."},{"verdict":"오답","why":"요구사항이나 아키텍처를 이해하기 어렵거나 핵심 기술에 위험이 있는 경우에 적합하다. 맞는 설명이다."}],"keywords":[{"term":"나선형 모델 단계","desc":"계획 및 정의 → 위험 분석 → 공학적 개발 → 고객 평가, 반복"},{"term":"나선형 모델 특징","desc":"점진적 개발, 매 주기 위험 분석, 대규모·고위험 프로젝트에 적합"},{"term":"보헴(Boehm)","desc":"나선형 모델 제안자"}],"memo":"나선형의 핵심은 '돌 때마다 위험 분석'. 마지막에 한 번이라는 보기는 틀렸다."}},{"id":"written-2022-1-82","no":82,"unit":"정보시스템 구축 관리","q":"정보시스템과 관련한 다음 설명에 해당하는 것은?\n<img src=\"data/img/eip_written_20220305_082.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["고가용성 솔루션(HACMP)","점대점 연결 방식(Point-to-Point Mode)","스턱스넷(Stuxnet)","루팅(Rooting)"],"ans":1,"rate":58,"wiki":[{"title":"HACMP","url":"https://itwiki.kr/w/HACMP"}],"exp":{"concept":"고가용성(HA, High Availability) 솔루션은 서버에 장애가 나도 서비스가 끊기지 않도록 여러 시스템을 묶어 운영하는 기술이다. HACMP(High Availability Cluster Multi-Processing)는 공유 디스크를 중심으로 여러 시스템을 클러스터로 묶어, 한 시스템에 장애가 나면 다른 시스템이 업무를 이어받게 한다. 지문의 '공유 디스크', '클러스터링', '2개의 서버 연결'이 단서다.","choices":[{"verdict":"정답","why":"고가용성 솔루션(HACMP)은 공유 디스크를 중심으로 여러 시스템을 클러스터링해 업무 서버의 안정성을 높이는 솔루션이다. 지문과 일치한다."},{"verdict":"오답","why":"점대점 연결 방식(Point-to-Point Mode)은 두 장치를 1:1로 직접 연결하는 통신 방식이다."},{"verdict":"오답","why":"스턱스넷(Stuxnet)은 산업 제어 시스템(SCADA)을 노려 공격하는 악성 웜이다."},{"verdict":"오답","why":"루팅(Rooting)은 안드로이드 기기에서 관리자(root) 권한을 얻어 제한을 푸는 것이다."}],"keywords":[{"term":"HACMP","desc":"공유 디스크 기반 클러스터링으로 고가용성 제공"},{"term":"고가용성(HA)","desc":"장애가 나도 서비스를 계속 제공할 수 있는 성질"},{"term":"클러스터링(Clustering)","desc":"여러 시스템을 하나처럼 묶어 운영"}],"memo":"'클러스터링'과 '안정성(가용성)'이 같이 나오면 HACMP."}},{"id":"written-2022-1-83","no":83,"unit":"정보시스템 구축 관리","q":"위조된 매체 접근 제어(MAC) 주소를 지속적으로 네트워크로 흘려보내, 스위치 MAC 주소 테이블의 저장 기능을 혼란시켜 더미 허브(Dummy Hub)처럼 작동하게 하는 공격은?","choices":["Parsing","LAN Tapping","Switch Jamming","FTP Flooding"],"ans":3,"rate":63,"exp":{"concept":"스위치는 MAC 주소 테이블을 보고 프레임을 필요한 포트로만 보낸다. 그런데 위조된 MAC 주소를 계속 흘려보내 테이블을 가득 채우면, 스위치는 목적지를 몰라 모든 포트로 프레임을 뿌리는 더미 허브처럼 동작한다. 이 틈을 타 다른 사람의 트래픽을 엿보는 공격이 스위치 재밍(Switch Jamming)이다.","choices":[{"verdict":"오답","why":"Parsing(파싱)은 문장이나 데이터를 문법에 따라 분석하는 구문 분석 작업으로, 공격 기법이 아니다."},{"verdict":"오답","why":"LAN Tapping은 랜 회선에 장비를 물리적으로 연결해 신호를 가로채는 도청 방식으로, MAC 주소 테이블을 노리는 공격이 아니다."},{"verdict":"정답","why":"Switch Jamming은 위조 MAC 주소를 계속 보내 스위치의 MAC 주소 테이블을 채워 더미 허브처럼 동작하게 만드는 공격이다."},{"verdict":"오답","why":"FTP Flooding은 MAC 주소 테이블을 노리는 공격이 아니며, 이 문제의 정답과 관계없다."}],"keywords":[{"term":"스위치 재밍(Switch Jamming)","desc":"위조 MAC으로 스위치 MAC 테이블을 넘치게 해 허브처럼 동작시킴(MAC Flooding)"},{"term":"더미 허브(Dummy Hub)","desc":"받은 데이터를 모든 포트로 그대로 뿌리는 단순 장비"},{"term":"스니핑(Sniffing)","desc":"네트워크 패킷을 몰래 엿보는 공격"}],"memo":"스위치를 '방해(jamming)'해서 허브로 만든다. MAC 주소 테이블 혼란이면 스위치 재밍."}},{"id":"written-2022-1-84","no":84,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 스토리지 시스템은?\n<img src=\"data/img/eip_written_20220305_084.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["DAS","NAS","BSA","NFC"],"ans":1,"rate":71,"wiki":[{"title":"DAS","url":"https://itwiki.kr/w/DAS"}],"exp":{"concept":"DAS(Direct Attached Storage)는 하드디스크 같은 저장 장치를 서버(호스트)에 직접 연결하는 가장 단순한 스토리지 방식이다. 중간에 네트워크 장비 없이 호스트 버스 어댑터로 바로 연결한다. 지문의 '직접 연결', '네트워크 디바이스 없이'가 결정적 단서다.","choices":[{"verdict":"정답","why":"DAS는 저장 장치를 호스트 버스 어댑터에 직접 연결하며, 네트워크 디바이스 없이 구성된다. 지문과 일치한다."},{"verdict":"오답","why":"NAS(Network Attached Storage)는 저장 장치를 네트워크에 연결해 여러 서버가 네트워크를 통해 파일을 공유하는 방식이다."},{"verdict":"오답","why":"BSA는 출제 범위의 표준 스토리지 방식이 아니다."},{"verdict":"오답","why":"NFC(Near Field Communication)는 가까운 거리에서 데이터를 주고받는 무선 통신 기술로, 스토리지 시스템이 아니다."}],"keywords":[{"term":"DAS","desc":"서버에 저장 장치를 직접 연결"},{"term":"NAS","desc":"네트워크에 연결된 파일 공유형 저장 장치"},{"term":"SAN","desc":"전용 고속 네트워크(파이버 채널 등)로 서버와 저장 장치를 연결"}],"memo":"Direct는 '직접'. 네트워크 없이 바로 붙이면 DAS."}},{"id":"written-2022-1-85","no":85,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위해 일반적으로 수행하는 작업이 아닌 것은?","choices":["무결성 검사","응용 프로그램의 보안 설정 및 패치(Patch) 적용","중단 프로세스 및 닫힌 포트 위주로 확인","불필요한 서비스 및 악성 프로그램의 확인과 제거"],"ans":3,"rate":82,"exp":{"concept":"취약점 관리는 시스템의 약점을 찾아 보완하는 활동이다. 파일이 바뀌지 않았는지 무결성을 검사하고, 보안 설정과 패치를 적용하고, 불필요한 서비스와 악성 프로그램을 제거한다. 공격은 실행 중인 프로세스와 열린 포트를 통해 들어오므로 그쪽을 중심으로 점검한다.","choices":[{"verdict":"오답","why":"중요 파일이 변조되지 않았는지 무결성 검사를 하는 것은 취약점 관리 작업이다."},{"verdict":"오답","why":"응용 프로그램의 보안 설정과 패치 적용은 취약점 관리의 기본 작업이다."},{"verdict":"정답","why":"취약점 점검은 실행 중인 프로세스와 열린 포트를 중심으로 확인해야 한다. 중단된 프로세스와 닫힌 포트 위주로 확인하는 것은 맞지 않다."},{"verdict":"오답","why":"불필요한 서비스와 악성 프로그램을 찾아 제거하는 것은 취약점 관리 작업이다."}],"keywords":[{"term":"취약점 관리","desc":"무결성 검사, 보안 설정·패치, 불필요한 서비스·악성 프로그램 제거, 실행 프로세스·열린 포트 점검"},{"term":"패치(Patch)","desc":"발견된 오류나 보안 취약점을 고치는 업데이트"}],"memo":"공격자는 열린 문으로 들어온다. '닫힌 포트 위주'면 틀린 보기다."}},{"id":"written-2022-1-86","no":86,"unit":"정보시스템 구축 관리","q":"소프트웨어 생명주기 모델 중 V 모델과 관련한 설명으로 틀린 것은?","choices":["요구 분석 및 설계단계를 거치지 않으며 항상 통합 테스트를 중심으로 V 형태를 이룬다.","Perry에 의해 제안되었으며 세부적인 테스트 과정으로 구성되어 신뢰도 높은 시스템을 개발하는데 효과적이다.","개발 작업과 검증 작업 사이의 관계를 명확히 드러내 놓은 폭포수 모델의 변형이라고 볼 수 있다.","폭포수 모델이 산출물 중심이라면 V 모델은 작업과 결과의 검증에 초점을 둔다."],"ans":1,"rate":62,"exp":{"concept":"V 모델은 폭포수 모델을 변형해, 개발의 각 단계(요구 분석, 설계, 구현)에 대응하는 테스트 단계(인수, 시스템, 통합, 단위 테스트)를 V자 모양으로 짝지어 놓은 모델이다. 왼쪽으로 내려가며 분석·설계하고, 오른쪽으로 올라가며 각 단계를 검증한다.","choices":[{"verdict":"정답","why":"V 모델은 요구 분석과 설계 단계를 거치며, 그 각각이 테스트 단계와 짝을 이룬다. 요구 분석과 설계를 거치지 않는다는 것은 틀린 설명이다."},{"verdict":"오답","why":"교재에서 Perry가 제안한 모델로 소개하며, 세부적인 테스트 과정으로 구성되어 신뢰도 높은 시스템 개발에 효과적이다. 맞는 설명이다."},{"verdict":"오답","why":"개발 작업과 검증 작업 사이의 관계를 명확히 드러낸 폭포수 모델의 변형이다. 맞는 설명이다."},{"verdict":"오답","why":"폭포수 모델이 산출물 중심이라면 V 모델은 작업과 결과의 검증에 초점을 둔다. 맞는 설명이다."}],"keywords":[{"term":"V 모델 짝","desc":"요구 분석-인수 테스트, 시스템 설계-시스템 테스트, 상세 설계-통합 테스트, 코딩-단위 테스트"},{"term":"폭포수 모델","desc":"단계를 순서대로 한 번씩 진행하는 선형 순차 모델"}],"memo":"V의 왼쪽은 만들기(분석·설계), 오른쪽은 확인하기(테스트). 분석·설계가 없으면 V가 성립하지 않는다."}},{"id":"written-2022-1-87","no":87,"unit":"정보시스템 구축 관리","q":"블루투스(Bluetooth) 공격과 해당 공격에 대한 설명이 올바르게 연결된 것은?","choices":["블루버그(BlueBug) - 블루투스의 취약점을 활용하여 장비의 파일에 접근하는 공격으로 OPP를 사용하여 정보를 열람","블루스나프(BlueSnarf) - 블루투스를 이용해 스팸처럼 명함을 익명으로 퍼뜨리는 것","블루프린팅(BluePrinting) - 블루투스 공격 장치의 검색 활동을 의미","블루재킹(BlueJacking) - 블루투스 장비사이의 취약한 연결 관리를 악용한 공격"],"ans":3,"rate":53,"wiki":[{"title":"블루프린팅","url":"https://itwiki.kr/w/블루프린팅"},{"title":"블루투스","url":"https://itwiki.kr/w/블루투스"}],"exp":{"concept":"블루투스 공격은 이름과 하는 일을 정확히 짝지어 외워야 한다. 블루버그는 취약한 연결 관리를 악용해 기기를 조종하고, 블루스나프는 OPP로 파일에 접근하고, 블루재킹은 명함처럼 스팸 메시지를 뿌리고, 블루프린팅은 공격할 블루투스 장치를 검색한다. 이 문제의 보기는 블루프린팅만 맞고 나머지는 설명이 서로 뒤섞여 있다.","choices":[{"verdict":"오답","why":"OPP(Object Push Profile)를 이용해 장비의 파일에 접근하는 공격은 블루스나프(BlueSnarf)다. 블루버그와 연결이 틀렸다."},{"verdict":"오답","why":"블루투스로 스팸처럼 명함(메시지)을 익명으로 퍼뜨리는 것은 블루재킹(BlueJacking)이다. 블루스나프와 연결이 틀렸다."},{"verdict":"정답","why":"블루프린팅(BluePrinting)은 공격할 블루투스 장치를 찾는 검색 활동이다. 올바른 연결이다."},{"verdict":"오답","why":"블루투스 장비 사이의 취약한 연결 관리를 악용하는 공격은 블루버그(BlueBug)다. 블루재킹과 연결이 틀렸다."}],"keywords":[{"term":"블루버그(BlueBug)","desc":"취약한 연결 관리를 악용해 기기를 원격 조종"},{"term":"블루스나프(BlueSnarf)","desc":"OPP를 이용해 인증 없이 파일·정보에 접근"},{"term":"블루재킹(BlueJacking)","desc":"명함처럼 스팸 메시지를 익명으로 전송"},{"term":"블루프린팅(BluePrinting)","desc":"공격 대상 블루투스 장치 검색"}],"memo":"파일 접근은 스나프, 스팸 명함은 재킹, 장치 검색은 프린팅, 기기 조종은 버그. 기능과 이름을 짝으로 외우자."}},{"id":"written-2022-1-88","no":88,"unit":"정보시스템 구축 관리","q":"DoS(Denial of Service) 공격과 관련한 내용으로 틀린 것은?","choices":["Ping of Death 공격은 정상 크기보다 큰 ICMP 패킷을 작은 조각(Fragment)으로 쪼개어 공격 대상이 조각화 된 패킷을 처리하게 만드는 공격 방법이다.","Smurf 공격은 멀티캐스트(Multicast)를 활용하여 공격 대상이 네트워크의 임의의 시스템에 패킷을 보내게 만드는 공격이다.","SYN Flooding은 존재하지 않는 클라이언트가 서버별로 한정된 접속 가능 공간에 접속한 것처럼 속여 다른 사용자가 서비스를 이용하지 못하게 하는 것이다.","Land 공격은 패킷 전송 시 출발지 IP주소와 목적지 IP주소 값을 똑같이 만들어서 공격 대상에게 보내는 공격 방법이다."],"ans":2,"rate":53,"wiki":[{"title":"스머프 공격","url":"https://itwiki.kr/w/스머프 공격"},{"title":"SYN 플러딩","url":"https://itwiki.kr/w/SYN 플러딩"},{"title":"랜드_어택","url":"https://itwiki.kr/w/랜드_어택"}],"exp":{"concept":"DoS(서비스 거부) 공격은 대상 시스템의 자원을 고갈시켜 정상 사용자가 서비스를 쓰지 못하게 하는 공격이다. 스머프(Smurf) 공격은 출발지 주소를 공격 대상의 IP로 위조한 ICMP 요청을 네트워크 전체에 브로드캐스트해서, 수많은 응답이 공격 대상에게 몰리게 만든다. 멀티캐스트가 아니라 브로드캐스트를 이용한다는 점이 핵심이다.","choices":[{"verdict":"오답","why":"Ping of Death는 정상 크기보다 큰 ICMP 패킷을 작은 조각(Fragment)으로 쪼개 보내 공격 대상이 조각을 처리하느라 마비되게 하는 공격이다. 맞는 설명이다."},{"verdict":"정답","why":"Smurf 공격은 멀티캐스트가 아니라 브로드캐스트(Broadcast)를 이용해 다수의 시스템이 공격 대상에게 응답 패킷을 보내게 만든다. 틀린 설명이다."},{"verdict":"오답","why":"SYN Flooding은 존재하지 않는 클라이언트가 접속한 것처럼 SYN 패킷만 보내 서버의 접속 대기 공간을 가득 채우는 공격이다. 맞는 설명이다."},{"verdict":"오답","why":"Land 공격은 출발지 IP와 목적지 IP를 같게 만들어 보내 공격 대상이 자기 자신에게 계속 응답하게 하는 공격이다. 맞는 설명이다."}],"keywords":[{"term":"Smurf","desc":"출발지를 위조한 ICMP 요청을 브로드캐스트해 응답을 공격 대상에 집중"},{"term":"Ping of Death","desc":"규정 크기를 넘는 ICMP 패킷을 조각내어 전송"},{"term":"SYN Flooding","desc":"TCP 3-way 핸드셰이크를 악용해 접속 대기 공간 고갈"},{"term":"Land Attack","desc":"출발지 IP = 목적지 IP로 위조"}],"memo":"Smurf는 브로드캐스트. '멀티캐스트'로 바꿔 놓은 보기에 속지 말자."}},{"id":"written-2022-1-89","no":89,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 시스템은?\n<img src=\"data/img/eip_written_20220305_089.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Apache","Hadoop","Honeypot","MapReduce"],"ans":3,"rate":74,"wiki":[{"title":"허니팟","url":"https://itwiki.kr/w/허니팟"},{"title":"해킹","url":"https://itwiki.kr/w/해킹"},{"title":"제로데이 공격","url":"https://itwiki.kr/w/제로데이 공격"}],"exp":{"concept":"허니팟(Honeypot)은 공격자를 속이려고 일부러 허술하게 만들어 둔 가짜 시스템이다. 실제로 공격당하는 것처럼 보이게 해서 크래커를 붙잡아 두고, 그동안 공격 기법과 추적 정보를 수집한다. 꿀단지로 벌레를 꾀어내는 것과 같아서 쉽게 노출되고 쉽게 공격할 수 있어 보여야 한다.","choices":[{"verdict":"오답","why":"Apache는 웹 서버 소프트웨어로, 침입자를 유인하는 시스템이 아니다."},{"verdict":"오답","why":"Hadoop은 대용량 데이터를 여러 컴퓨터에서 분산 저장·처리하는 오픈 소스 프레임워크다."},{"verdict":"정답","why":"Honeypot은 비정상적인 접근을 탐지하고 공격 정보를 수집하기 위해 의도적으로 설치해 둔 유인 시스템이다. 지문과 일치한다."},{"verdict":"오답","why":"MapReduce는 대용량 데이터를 Map 단계와 Reduce 단계로 나누어 병렬 처리하는 프로그래밍 모델이다."}],"keywords":[{"term":"허니팟(Honeypot)","desc":"공격자를 유인해 정보를 수집하는 가짜 시스템"},{"term":"허니넷(Honeynet)","desc":"여러 허니팟으로 구성한 유인용 네트워크"},{"term":"IDS","desc":"침입 탐지 시스템, 비정상 접근을 탐지"}],"memo":"꿀단지(Honeypot)로 벌레(크래커)를 꾄다. '유인', '탐지 목적 의도적 설치'면 허니팟."}},{"id":"written-2022-1-90","no":90,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 IT 기술은?\n<img src=\"data/img/eip_written_20220305_090.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["StackGuard","Docker","Cipher Container","Scytale"],"ans":2,"rate":72,"wiki":[{"title":"도커","url":"https://itwiki.kr/w/도커"}],"exp":{"concept":"도커(Docker)는 애플리케이션과 실행에 필요한 환경을 컨테이너라는 가벼운 상자에 담아, 어디서든 똑같이 배포하고 실행할 수 있게 해 주는 오픈 소스 엔진이다. 지문의 '컨테이너 응용 프로그램 배포 자동화', '오픈 소스 엔진'이 결정적 단서다.","choices":[{"verdict":"오답","why":"StackGuard는 스택에 카나리(canary) 값을 넣어 두고 그 값이 바뀌면 버퍼 오버플로로 판단해 실행을 멈추는 보호 기법이다."},{"verdict":"정답","why":"Docker는 컨테이너 응용 프로그램의 배포를 자동화하는 오픈 소스 엔진이다. 지문과 일치한다."},{"verdict":"오답","why":"Cipher Container는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"Scytale(스키테일)은 고대 그리스에서 막대에 띠를 감아 글자를 적던 전치 암호다."}],"keywords":[{"term":"Docker","desc":"컨테이너 기반 애플리케이션 배포 자동화 오픈 소스 엔진"},{"term":"컨테이너(Container)","desc":"애플리케이션과 실행 환경을 묶은 가벼운 격리 단위"},{"term":"StackGuard","desc":"카나리 값으로 스택 버퍼 오버플로를 탐지하는 기법"}],"memo":"도커(Docker)는 '부두 노동자'. 컨테이너를 옮기고 배치하는 일을 자동화한다."}},{"id":"written-2022-1-91","no":91,"unit":"정보시스템 구축 관리","q":"간트 차트(Gantt Chart)에 대한 설명으로 틀린 것은?","choices":["프로젝트를 이루는 소작업 별로 언제 시작되고 언제 끝나야 하는지를 한 눈에 볼 수 있도록 도와준다.","자원 배치 계획에 유용하게 사용된다.","CPM 네트워크로부터 만드는 것이 가능하다.","수평 막대의 길이는 각 작업(Task)에 필요한 인원수를 나타낸다."],"ans":4,"rate":72,"wiki":[{"title":"간트 차트","url":"https://itwiki.kr/w/간트 차트"}],"exp":{"concept":"간트 차트(Gantt Chart)는 프로젝트의 각 작업을 언제 시작해 언제 끝내는지를 시간 축 위에 수평 막대로 그린 일정표다. 막대의 길이는 작업 기간을 뜻한다. 작업의 일정과 이정표를 한눈에 볼 수 있어 자원 배치 계획에도 쓰인다.","choices":[{"verdict":"오답","why":"소작업별 시작·종료 시점을 한눈에 볼 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"작업 일정이 보이므로 자원 배치 계획에 유용하다. 맞는 설명이다."},{"verdict":"오답","why":"CPM 네트워크에서 구한 작업 일정을 바탕으로 간트 차트를 만들 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"수평 막대의 길이는 작업 기간을 나타낸다. 필요한 인원수를 나타낸다는 것은 틀린 설명이다."}],"keywords":[{"term":"간트 차트","desc":"작업 일정을 수평 막대로 표시, 막대 길이 = 작업 기간"},{"term":"PERT","desc":"낙관치·기대치·비관치로 일정을 추정하는 네트워크 기법"},{"term":"CPM","desc":"임계 경로로 최소 완료 기간을 구하는 네트워크 기법"}],"memo":"간트 차트의 가로축은 시간이다. 막대가 길면 '오래 걸리는' 작업이다."}},{"id":"written-2022-1-92","no":92,"unit":"정보시스템 구축 관리","q":"Python 기반의 웹 크롤링(Web Crawling) 프레임워크로 옳은 것은?","choices":["Li-fi","Scrapy","CrawlCat","SBAS"],"ans":2,"rate":65,"exp":{"concept":"웹 크롤링은 프로그램이 웹 페이지를 자동으로 돌아다니며 정보를 수집하는 것이다. 스크래피(Scrapy)는 Python으로 만든 대표적인 웹 크롤링 프레임워크로, 웹 페이지에서 원하는 데이터를 뽑아내는 기능을 제공한다.","choices":[{"verdict":"오답","why":"Li-Fi(Light Fidelity)는 LED 빛을 이용해 데이터를 전송하는 무선 통신 기술이다."},{"verdict":"정답","why":"Scrapy는 Python 기반의 웹 크롤링 프레임워크다."},{"verdict":"오답","why":"CrawlCat은 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"SBAS(Satellite Based Augmentation System)는 위성을 이용해 GPS 위치 오차를 보정하는 위성 기반 보강 시스템이다."}],"keywords":[{"term":"Scrapy","desc":"Python 기반 웹 크롤링 프레임워크"},{"term":"웹 크롤링(Web Crawling)","desc":"웹 페이지를 자동 탐색하며 데이터를 수집"},{"term":"Li-Fi","desc":"가시광선(LED)을 이용한 무선 통신"}],"memo":"웹에서 데이터를 긁어모으는(scrape) Python(py) 도구라고 연결하면 Scrapy를 기억하기 쉽다."}},{"id":"written-2022-1-93","no":93,"unit":"정보시스템 구축 관리","q":"Secure 코딩에서 입력 데이터의 보안 약점과 관련한 설명으로 틀린 것은?","choices":["SQL 삽입 : 사용자의 입력 값 등 외부 입력 값이 SQL 쿼리에 삽입되어 공격","크로스사이트 스크립트 : 검증되지 않은 외부 입력 값에 의해 브라우저에서 악의적인 코드가 실행","운영체제 명령어 삽입 : 운영체제 명령어 파라미터 입력 값이 적절한 사전검증을 거치지 않고 사용되어 공격자가 운영체제 명령어를 조작","자원 삽입 : 사용자가 내부 입력 값을 통해 시스템 내에 사용이 불가능한 자원을 지속적으로 입력함으로써 시스템에 과부하 발생"],"ans":4,"rate":56,"exp":{"concept":"시큐어 코딩에서 입력 데이터 검증 및 표현 약점은, 외부 입력값을 제대로 검사하지 않고 써서 생기는 문제다. SQL 삽입, 크로스사이트 스크립트(XSS), 운영체제 명령어 삽입, 자원 삽입 등이 있다. 자원 삽입(Resource Injection)은 외부 입력값을 검증 없이 파일 경로나 포트 번호 같은 시스템 자원 식별자로 사용해, 공격자가 자원을 마음대로 조작하게 되는 약점이다.","choices":[{"verdict":"오답","why":"SQL 삽입은 외부 입력값이 SQL 쿼리에 그대로 삽입되어 공격자가 쿼리를 조작하는 약점이다. 맞는 설명이다."},{"verdict":"오답","why":"크로스사이트 스크립트(XSS)는 검증되지 않은 외부 입력값 때문에 사용자 브라우저에서 악성 스크립트가 실행되는 약점이다. 맞는 설명이다."},{"verdict":"오답","why":"운영체제 명령어 삽입은 검증 없이 쓰인 입력값으로 공격자가 운영체제 명령어를 조작하는 약점이다. 맞는 설명이다."},{"verdict":"정답","why":"자원 삽입은 외부 입력값을 검증 없이 시스템 자원(파일, 포트 등)의 식별자로 사용해 자원을 조작당하는 약점이다. 자원을 계속 입력해 과부하를 일으킨다는 설명은 틀렸다."}],"keywords":[{"term":"SQL 삽입(SQL Injection)","desc":"입력값으로 SQL 쿼리를 조작"},{"term":"XSS(Cross Site Scripting)","desc":"웹 페이지에 악성 스크립트를 삽입해 사용자 브라우저에서 실행"},{"term":"운영체제 명령어 삽입","desc":"입력값으로 OS 명령어를 조작"},{"term":"자원 삽입(Resource Injection)","desc":"입력값으로 파일 경로·포트 등 자원 식별자를 조작"}],"memo":"삽입(Injection) 약점은 모두 '검증 안 된 외부 입력이 무언가를 조작'하는 구조다. '과부하'는 서비스 거부 공격의 설명이다."}},{"id":"written-2022-1-94","no":94,"unit":"정보시스템 구축 관리","q":"Windows 파일 시스템인 FAT와 비교했을 때의 NTFS의 특징이 아닌 것은?","choices":["보안에 취약","대용량 볼륨에 효율적","자동 압축 및 안정성","저용량 볼륨에서의 속도 저하"],"ans":1,"rate":59,"exp":{"concept":"FAT와 NTFS는 Windows의 파일 시스템이다. NTFS는 FAT보다 나중에 나온 방식으로, 파일·폴더별 접근 권한과 암호화를 지원해 보안이 뛰어나고, 대용량 볼륨에 효율적이며, 자동 압축과 저널링을 통한 안정성을 갖추었다. 다만 구조가 복잡해 저용량 볼륨에서는 FAT보다 속도가 느리다.","choices":[{"verdict":"정답","why":"NTFS는 파일별 권한 설정과 암호화를 지원해 FAT보다 보안이 강하다. 보안에 취약하다는 것은 NTFS의 특징이 아니다."},{"verdict":"오답","why":"NTFS는 대용량 볼륨을 효율적으로 다룬다. NTFS의 특징이다."},{"verdict":"오답","why":"NTFS는 자동 압축 기능과 오류 복구를 위한 안정성을 제공한다. NTFS의 특징이다."},{"verdict":"오답","why":"NTFS는 저용량 볼륨에서는 FAT보다 속도가 느리다. NTFS의 특징으로 알려진 내용이다."}],"keywords":[{"term":"FAT","desc":"구조가 단순한 파일 시스템, 저용량 볼륨에 유리, 보안 기능이 약함"},{"term":"NTFS","desc":"보안(권한·암호화), 대용량 효율, 압축, 저널링 안정성, 저용량에서는 상대적으로 느림"}],"memo":"NTFS는 FAT의 단점을 보완한 후속작이다. 보안이 약하다는 건 FAT 쪽 이야기다."}},{"id":"written-2022-1-95","no":95,"unit":"정보시스템 구축 관리","q":"DES는 몇 비트의 암호화 알고리즘인가?","choices":["8","24","64","132"],"ans":3,"rate":79,"wiki":[{"title":"DES","url":"https://itwiki.kr/w/DES"}],"exp":{"concept":"DES(Data Encryption Standard)는 미국 표준으로 쓰였던 대칭 키(개인 키) 블록 암호다. 평문을 64비트 블록 단위로 암호화하고, 키도 64비트지만 그중 8비트는 패리티 비트라 실제 키 길이는 56비트다. 키가 짧아 안전성이 떨어지자 AES가 새 표준이 되었다.","choices":[{"verdict":"오답","why":"8비트는 DES의 블록 크기나 키 길이가 아니다. DES의 64비트 키 중 패리티로 쓰이는 비트 수가 8비트다."},{"verdict":"오답","why":"24비트는 DES와 관계없는 값이다."},{"verdict":"정답","why":"DES는 64비트 블록 단위로 암호화하는 알고리즘이며, 실제 키 길이는 56비트다."},{"verdict":"오답","why":"132비트는 DES와 관계없는 값이다. AES는 128비트 블록과 128·192·256비트 키를 쓴다."}],"keywords":[{"term":"DES","desc":"64비트 블록, 56비트 실제 키, 대칭 키 블록 암호"},{"term":"AES","desc":"128비트 블록, 128·192·256비트 키, DES의 후속 표준"},{"term":"SEED","desc":"한국인터넷진흥원(KISA)이 개발한 128비트 블록 암호"}],"memo":"DES는 '블록 64, 키 56', AES는 '블록 128'. 숫자 짝으로 외우자."}},{"id":"written-2022-1-96","no":96,"unit":"정보시스템 구축 관리","q":"리눅스에서 생성된 파일 권한이 644일 경우 umask 값은?","choices":["022","666","777","755"],"ans":1,"rate":63,"exp":{"concept":"리눅스에서 새로 만드는 파일의 기본 권한은 666(rw-rw-rw-), 디렉터리는 777(rwxrwxrwx)이다. umask는 이 기본 권한에서 빼 줄 권한을 지정하는 값이다. 파일 권한이 644(rw-r--r--)가 되었다면 666에서 022를 뺀 것이므로 umask는 022다.","choices":[{"verdict":"정답","why":"파일 기본 권한 666에서 umask 022를 빼면 644가 된다."},{"verdict":"오답","why":"umask가 666이면 파일 권한은 666 - 666 = 000(아무 권한 없음)이 된다."},{"verdict":"오답","why":"umask가 777이면 모든 권한이 빠져 파일 권한은 000이 된다."},{"verdict":"오답","why":"755는 umask가 022일 때 새로 만든 디렉터리의 권한(777 - 022)이지, umask 값이 아니다."}],"keywords":[{"term":"umask","desc":"새 파일·디렉터리 생성 시 기본 권한에서 제외할 권한"},{"term":"파일 기본 권한","desc":"666, umask 022 적용 시 644"},{"term":"디렉터리 기본 권한","desc":"777, umask 022 적용 시 755"},{"term":"권한 숫자","desc":"r=4, w=2, x=1을 소유자·그룹·기타 순으로 합산"}],"memo":"파일은 666에서, 디렉터리는 777에서 umask를 뺀다. 644 ↔ 022, 755 ↔ 022."}},{"id":"written-2022-1-97","no":97,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 로그 파일은?\n<img src=\"data/img/eip_written_20220305_097.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["tapping","xtslog","linuxer","wtmp"],"ans":4,"rate":58,"wiki":[{"title":"리눅스 wtmp","url":"https://itwiki.kr/w/리눅스 wtmp"}],"exp":{"concept":"리눅스는 로그인 기록을 여러 로그 파일에 나눠 저장한다. wtmp는 사용자의 성공한 로그인·로그아웃 기록과 시스템 종료·시작 시간을 저장하며 last 명령으로 확인한다. 현재 로그인한 사용자는 utmp, 실패한 로그인은 btmp에 기록된다.","choices":[{"verdict":"오답","why":"tapping은 리눅스의 표준 로그 파일이 아니다."},{"verdict":"오답","why":"xtslog는 리눅스의 표준 로그 파일이 아니다."},{"verdict":"오답","why":"linuxer는 리눅스의 표준 로그 파일이 아니다."},{"verdict":"정답","why":"wtmp는 사용자의 성공한 로그인·로그아웃 정보와 시스템 종료·시작 시간을 기록하는 로그 파일이다. 지문과 일치한다."}],"keywords":[{"term":"wtmp","desc":"성공한 로그인·로그아웃, 시스템 종료·시작 기록(last 명령)"},{"term":"utmp","desc":"현재 로그인한 사용자 정보(who, w 명령)"},{"term":"btmp","desc":"실패한 로그인 기록(lastb 명령)"},{"term":"lastlog","desc":"사용자별 마지막 로그인 기록"}],"memo":"현재 접속은 utmp, 성공한 로그인 이력과 시스템 시작·종료는 wtmp, 실패한 로그인은 btmp. 세 파일을 짝으로 외우자."}},{"id":"written-2022-1-98","no":98,"unit":"정보시스템 구축 관리","q":"상향식 비용 산정 기법 중 LOC(원시 코드 라인 수) 기법에서 예측치를 구하기 위해 사용하는 항목이 아닌 것은?","choices":["낙관치","기대치","비관치","모형치"],"ans":4,"rate":70,"exp":{"concept":"LOC(원시 코드 라인 수) 기법은 각 기능의 코드 줄 수를 세 가지 값으로 추정한 뒤 가중 평균으로 예측치를 구한다. 세 값은 낙관치(가장 적게), 기대치(가장 가능성 높게, 중간치), 비관치(가장 많게)이고, 예측치 = (낙관치 + 4 × 기대치 + 비관치) ÷ 6이다.","choices":[{"verdict":"오답","why":"낙관치는 가장 적게 걸릴 것으로 예상한 라인 수로, 예측치 계산에 쓰인다."},{"verdict":"오답","why":"기대치(중간치)는 가장 가능성이 높은 라인 수로, 4배 가중치를 주어 예측치 계산에 쓰인다."},{"verdict":"오답","why":"비관치는 가장 많이 걸릴 것으로 예상한 라인 수로, 예측치 계산에 쓰인다."},{"verdict":"정답","why":"모형치는 LOC 기법의 예측치 계산에 쓰이는 항목이 아니다."}],"keywords":[{"term":"LOC 예측치","desc":"(낙관치 + 4 × 기대치 + 비관치) ÷ 6"},{"term":"노력(인월)","desc":"개발 기간 × 투입 인원, 또는 LOC ÷ 1인당 월평균 생산 코드 라인 수"},{"term":"상향식 비용 산정","desc":"LOC 기법, 개발 단계별 인월수 기법"}],"memo":"'낙기비' 세 값만 쓴다. 가운데 기대치에 4배를 곱하는 것을 잊지 말자."}},{"id":"written-2022-1-99","no":99,"unit":"정보시스템 구축 관리","q":"OSI 7 Layer 전 계층의 프로토콜과 패킷 내부의 콘텐츠를 파악하여 침입 시도, 해킹 등을 탐지하고 트래픽을 조정하기 위한 패킷 분석 기술은?","choices":["PLCP(Packet Level Control Processor)","Traffic Distributor","Packet Tree","DPI(Deep Packet Inspection)"],"ans":4,"rate":54,"wiki":[{"title":"심층 패킷 분석","url":"https://itwiki.kr/w/심층 패킷 분석"}],"exp":{"concept":"DPI(Deep Packet Inspection, 심층 패킷 분석)는 패킷의 헤더뿐 아니라 안에 담긴 내용(페이로드)까지 OSI 7계층 전체에 걸쳐 들여다보는 기술이다. 이를 통해 침입 시도나 해킹을 탐지하고, 트래픽을 분류·조정할 수 있다. 우편물의 겉봉투만 보는 게 아니라 뜯어서 내용물까지 확인하는 것과 같다.","choices":[{"verdict":"오답","why":"PLCP(Packet Level Control Processor)는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"Traffic Distributor는 패킷 내부 콘텐츠를 분석해 침입을 탐지하는 기술을 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"Packet Tree는 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"DPI(Deep Packet Inspection)는 OSI 7계층 전체의 프로토콜과 패킷 내부 콘텐츠를 분석해 침입·해킹을 탐지하고 트래픽을 조정하는 기술이다."}],"keywords":[{"term":"DPI(Deep Packet Inspection)","desc":"패킷 헤더와 내부 콘텐츠까지 분석하는 심층 패킷 분석 기술"},{"term":"IDS / IPS","desc":"침입 탐지 시스템 / 침입 방지 시스템"}],"memo":"Deep(깊이) 들여다본다 = 패킷 내용까지 본다. '콘텐츠 파악'이면 DPI."}},{"id":"written-2022-1-100","no":100,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론의 테일러링(Tailoring)과 관련한 설명으로 틀린 것은?","choices":["프로젝트 수행 시 예상되는 변화를 배제하고 신속히 진행하여야 한다.","프로젝트에 최적화된 개발 방법론을 적용하기 위해 절차, 산출물 등을 적절히 변경하는 활동이다.","관리 측면에서의 목적 중 하나는 최단기간에 안정적인 프로젝트 진행을 위한 사전 위험을 식별하고 제거하는 것이다.","기술적 측면에서의 목적 중 하나는 프로젝트에 최적화된 기술 요소를 도입하여 프로젝트 특성에 맞는 최적의 기법과 도구를 사용하는 것이다."],"ans":1,"rate":67,"exp":{"concept":"테일러링(Tailoring)은 옷을 몸에 맞게 고쳐 입듯, 표준 개발 방법론의 절차·산출물·기법 등을 프로젝트 특성에 맞게 수정해 적용하는 작업이다. 프로젝트 중에 생길 변화를 미리 고려해 반영하는 것이 목적이므로, 변화를 배제한다는 것은 테일러링 취지와 반대다.","choices":[{"verdict":"정답","why":"테일러링은 프로젝트 수행 중 예상되는 변화를 배제하는 것이 아니라 고려해 방법론을 조정하는 활동이다. 틀린 설명이다."},{"verdict":"오답","why":"프로젝트에 최적화된 방법론을 적용하기 위해 절차, 산출물 등을 적절히 변경하는 활동이다. 맞는 설명이다."},{"verdict":"오답","why":"관리 측면에서는 최단 기간에 안정적으로 프로젝트를 진행하도록 사전 위험을 식별하고 제거하는 것이 목적 중 하나다. 맞는 설명이다."},{"verdict":"오답","why":"기술 측면에서는 프로젝트에 최적화된 기술 요소를 도입해 특성에 맞는 최적의 기법과 도구를 사용하는 것이 목적 중 하나다. 맞는 설명이다."}],"keywords":[{"term":"테일러링(Tailoring)","desc":"개발 방법론을 프로젝트 특성에 맞게 수정·보완"},{"term":"테일러링 내부 기준","desc":"목표 환경, 요구사항, 프로젝트 규모, 보유 기술"},{"term":"테일러링 외부 기준","desc":"법적 제약사항, 표준 품질 기준"}],"memo":"테일러(재단사)는 몸에 맞게 고친다. 변화를 '배제'하면 고칠 이유가 없다."}}]};